const SCENES = [{"id": "p000", "chapter": "PROLOGUE / 観測者", "bg": "black", "system": "N.E.M.O. OBSERVATION NETWORK\nCONNECTING...\nAUTHORIZATION ACCEPTED.\nOBSERVER ID : 0417\nTARGET : NEMO", "text": ""}, {"id": "p010", "bg": "black", "speaker": "SYSTEM", "text": "観測対象への接触は禁止されています。\n\n必要以上の介入は禁止されています。\n\n私的感情による記録の改変は禁止されています。"}, {"id": "p020", "bg": "black", "speaker": "SYSTEM", "text": "あなたの任務は、観測し、記録し、必要な場合のみ保護することです。"}, {"id": "p030", "bg": "black", "speaker": "SYSTEM", "text": "NEMOの人生は、あなたのものではありません。"}, {"id": "p040", "bg": "street", "system": "17:41:03\nNEMO、指定区域へ到着。\n健康状態、良好。\n周辺に危険因子なし。", "text": "夕方の小さな商店街。\n少し離れたコンビニの前に、一人の女の子がいる。\n\n猫耳。紙袋。肉まん。"}, {"id": "p050", "bg": "street", "speaker": "榊", "text": "……肉まん。"}, {"id": "p060", "bg": "street", "text": "ねもは、足元にいた猫へ肉まんの皮を少しだけ見せる。\n猫は食べない。"}, {"id": "p070", "bg": "street", "speaker": "ねも", "text": "いらないの？"}, {"id": "p080", "bg": "street", "speaker": "ねも", "text": "そっか。"}, {"id": "p090", "bg": "street", "speaker": "榊", "text": "……何してるんだ。"}, {"id": "p100", "bg": "street", "system": "入力：\nNEMO、野良猫と接触。\n\nDELETE\n\n入力：\nNEMO、野良猫に食物を与えようとする。\n\nDELETE\n\n入力：\n特記事項なし。\n\nRECORD SAVED.", "text": ""}, {"id": "p110", "bg": "street", "speaker": "SYSTEM", "text": "警告。\n観測者による主観的記録を検出しました。\n対象行動を正確に記録してください。"}, {"id": "p120", "bg": "street", "speaker": "榊", "text": "これのどこが重要なんだよ。"}, {"id": "p130", "bg": "street", "text": "18:02:17。\nねもが移動を始める。\n\nその時、突然振り返った。\n真正面からこちらを見る。"}, {"id": "p140", "bg": "street", "text": "ねもが歩いてくる。\n二十三メートル。\n十七メートル。\n十二メートル。\n七メートル。\n\nそして、目の前で止まった。"}, {"id": "p150", "bg": "street", "speaker": "ねも", "text": "昨日もいたよね？", "choice": [{"label": "人違いです", "response": "……たぶん、人違い。"}, {"label": "何のこと？", "response": "……たぶん、人違い。"}, {"label": "…………", "response": "……たぶん、人違い。"}], "choiceSpeaker": "榊"}, {"id": "p160", "bg": "street", "speaker": "ねも", "text": "そっか。"}, {"id": "p170", "bg": "street", "speaker": "ねも", "text": "でも、明日もいたら、人違いじゃないね。"}, {"id": "p180", "bg": "street", "system": "18:04:52\nNEMO、観測者を視認。\n18:05:07\n観測者との会話が発生。\n\n規定に基づき報告してください。", "text": ""}, {"id": "p190", "bg": "street", "system": "入力：\n特記事項なし。\n\nRECORD SAVED.", "text": "その日の記録には、彼女と初めて話したことは残らなかった。"}, {"id": "c1_000", "chapter": "CHAPTER 01 / 接触", "bg": "street", "text": "翌日。\n\n榊透は、昨日と同じ場所にいた。\n正確には、昨日より十二メートル離れた位置にいた。"}, {"id": "c1_010", "bg": "street", "speaker": "ねも", "text": "いた。"}, {"id": "c1_020", "bg": "street", "speaker": "ねも", "text": "やっぱり人違いじゃなかった。"}, {"id": "c1_030", "bg": "street", "speaker": "榊", "text": "昨日の人とは別人です。"}, {"id": "c1_040", "bg": "street", "speaker": "ねも", "text": "顔おんなじだよ。"}, {"id": "c1_050", "bg": "street", "speaker": "榊", "text": "似てる人です。"}, {"id": "c1_060", "bg": "street", "speaker": "ねも", "text": "服もおんなじ。"}, {"id": "c1_070", "bg": "street", "speaker": "榊", "text": "偶然です。"}, {"id": "c1_080", "bg": "street", "speaker": "ねも", "text": "靴も。"}, {"id": "c1_090", "bg": "street", "speaker": "榊", "text": "……よく見てるな。"}, {"id": "c1_100", "bg": "street", "speaker": "ねも", "text": "認めた。"}, {"id": "c1_110", "bg": "street", "speaker": "榊", "text": "認めてない。"}, {"id": "c1_120", "bg": "street", "speaker": "ねも", "text": "なんで毎日ここにいるの？"}, {"id": "c1_130", "bg": "street", "speaker": "榊", "text": "仕事。"}, {"id": "c1_140", "bg": "street", "speaker": "ねも", "text": "何の？"}, {"id": "c1_150", "bg": "street", "speaker": "榊", "text": "人を見る仕事。"}, {"id": "c1_160", "bg": "street", "text": "一瞬。\n榊は自分で言ってから黙った。"}, {"id": "c1_170", "bg": "street", "speaker": "榊", "text": "……接客業。"}, {"id": "c1_180", "bg": "street", "speaker": "ねも", "text": "接客してないじゃん。"}, {"id": "c1_190", "bg": "street", "speaker": "榊", "text": "休憩中。"}, {"id": "c1_200", "bg": "street", "speaker": "ねも", "text": "毎日？"}, {"id": "c1_210", "bg": "street", "speaker": "榊", "text": "休憩の多い会社なんだよ。"}, {"id": "c1_220", "bg": "street", "speaker": "ねも", "text": "いい会社だね。"}, {"id": "c1_230", "bg": "street", "speaker": "榊", "text": "最低の会社だよ。"}, {"id": "c1_240", "bg": "street", "text": "これは本音だった。"}, {"id": "c1_250", "bg": "street", "speaker": "ねも", "text": "名前は？"}, {"id": "c1_260", "bg": "street", "speaker": "榊", "text": "言わない。"}, {"id": "c1_270", "bg": "street", "speaker": "ねも", "text": "じゃあ仮の名前つける。"}, {"id": "c1_280", "bg": "street", "speaker": "榊", "text": "やめろ。"}, {"id": "c1_290", "bg": "street", "speaker": "ねも", "text": "肉まん二号。"}, {"id": "c1_300", "bg": "street", "speaker": "榊", "text": "最悪。"}, {"id": "c1_310", "bg": "street", "speaker": "ねも", "text": "一号はねも。"}, {"id": "c1_320", "bg": "street", "speaker": "榊", "text": "もっと最悪。"}, {"id": "c1_330", "bg": "street", "text": "ねもが笑う。\n榊も、ほんの少しだけ笑った。\n自分でも気づかない程度に。"}, {"id": "c1_340", "bg": "street", "speaker": "SYSTEM", "text": "FACE ANALYSIS ERROR\n観測者の表情変化を検出。\n任務への集中を維持してください。"}, {"id": "c1_350", "bg": "night", "system": "対象との接触時間：27分14秒\n規則外接触を確認。\n報告書を作成してください。", "text": "ねもの姿が見えなくなる。"}, {"id": "c1_360", "bg": "night", "system": "入力：\n特記事項なし。\n\nDELETE\n\n入力：\nNEMOとの会話が発生。\n\nDELETE\n\n入力：\n対象、安全上の異常なし。\n\nRECORD SAVED.", "text": ""}, {"id": "c1_370", "bg": "night", "system": "PERSONAL RECORD\n\nNEMO。\n思ったより、よく喋る。\n肉まんが好き。", "text": ""}, {"id": "c1_380", "bg": "night", "text": "榊は『NEMO』の文字を見る。\n一度消す。"}, {"id": "c1_390", "bg": "night", "system": "PERSONAL RECORD\n\nねも。\n思ったより、よく喋る。\n肉まんが好き。\n\nDAY 02 / SAVED.", "text": "今度は、消さなかった。"}, {"id": "c2_000", "chapter": "CHAPTER 02 / 介入", "bg": "rain", "system": "DAY 11\nWEATHER : RAIN\nOBSERVATION STATUS : ACTIVE", "text": "雨の日だった。\n\nねもは傘を持っていなかった。"}, {"id": "c2_010", "bg": "rain", "speaker": "榊", "text": "……学習しないな。"}, {"id": "c2_020", "bg": "rain", "text": "横断歩道の信号が変わる。\nねもが歩き出す。\n\nその向こうから、速度を落とさない自転車が来る。"}, {"id": "c2_030", "bg": "rain", "system": "危険接近を検出。\n保護要員 ETA : 6.2 sec\n推定衝突まで : 3.8 sec", "text": ""}, {"id": "c2_040", "bg": "rain", "text": "榊は考えなかった。\n\n端末を落として、走った。", "fx": "pulse"}, {"id": "c2_050", "bg": "rain", "speaker": "ねも", "text": "え――"}, {"id": "c2_060", "bg": "rain", "text": "腕を引く。\nねもの身体が榊の胸にぶつかる。\n\n自転車が、水しぶきを上げて目の前を抜けていった。"}, {"id": "c2_070", "bg": "rain", "speaker": "榊", "text": "前見ろ。"}, {"id": "c2_080", "bg": "rain", "speaker": "ねも", "text": "……ごめん。"}, {"id": "c2_090", "bg": "rain", "speaker": "榊", "text": "俺に謝るな。"}, {"id": "c2_100", "bg": "rain", "text": "ねもは、まだ榊の上着を掴んでいる。"}, {"id": "c2_110", "bg": "rain", "speaker": "ねも", "text": "肉まん二号。"}, {"id": "c2_120", "bg": "rain", "speaker": "榊", "text": "こんな時までそれかよ。"}, {"id": "c2_130", "bg": "rain", "speaker": "ねも", "text": "手、震えてる。"}, {"id": "c2_140", "bg": "rain", "speaker": "榊", "text": "寒いだけ。"}, {"id": "c2_150", "bg": "rain", "speaker": "ねも", "text": "嘘。"}, {"id": "c2_160", "bg": "rain", "text": "榊は何も答えなかった。"}, {"id": "c2_170", "bg": "black", "system": "INCIDENT REPORT\n観測者 0417 による直接介入を確認。\n\n他保護要員による対応可能性：87.4%\n\n介入理由を入力してください。", "text": ""}, {"id": "c2_180", "bg": "black", "system": "入力：\n緊急性が高かったため。\n\nSYSTEM RESPONSE :\n妥当性不足。補足を要求します。", "text": ""}, {"id": "c2_190", "bg": "black", "speaker": "榊", "text": "……。"}, {"id": "c2_200", "bg": "black", "system": "介入理由を入力してください。", "text": "", "choice": [{"label": "対象を保護するため", "response": "対象を保護するため。"}, {"label": "反射的に身体が動いた", "response": "反射的に身体が動いた。"}, {"label": "入力しない", "response": "――――――。"}]}, {"id": "c2_210", "bg": "black", "speaker": "SYSTEM", "text": "回答を受理できません。\n監査フラグを付与します。"}, {"id": "c2_220", "bg": "night", "system": "PERSONAL RECORD / DAY 11", "text": "榊は、私的端末を開く。"}, {"id": "c2_230", "bg": "night", "system": "彼女が危なかった。\nだから助けた。\n\nそれだけだ。", "text": ""}, {"id": "c2_240", "bg": "night", "text": "数秒後。\n最後の一行を消す。"}, {"id": "c2_250", "bg": "night", "system": "彼女が危なかった。\n\n怖かった。", "text": ""}, {"id": "c2_260", "bg": "night", "text": "初めて、記録に感情を書いた。"}, {"id": "c3_000", "chapter": "CHAPTER 03 / 名前", "bg": "street", "system": "DAY 19\nOBSERVATION STATUS : ACTIVE\nAUDIT FLAG : 1", "text": "それから、榊は少しだけ距離を取った。"}, {"id": "c3_010", "bg": "street", "text": "十二メートル。\n二十メートル。\n三十五メートル。\n\nねもが近づけば、離れた。"}, {"id": "c3_020", "bg": "street", "speaker": "ねも", "text": "最近、逃げるね。"}, {"id": "c3_030", "bg": "street", "speaker": "榊", "text": "気のせい。"}, {"id": "c3_040", "bg": "street", "speaker": "ねも", "text": "じゃあ今日、逃げないで。"}, {"id": "c3_050", "bg": "street", "speaker": "榊", "text": "なんで。"}, {"id": "c3_060", "bg": "street", "speaker": "ねも", "text": "名前、まだ聞いてない。"}, {"id": "c3_070", "bg": "street", "speaker": "榊", "text": "肉まん二号でいいんだろ。"}, {"id": "c3_080", "bg": "street", "speaker": "ねも", "text": "飽きた。"}, {"id": "c3_090", "bg": "street", "speaker": "榊", "text": "ひどいな。"}, {"id": "c3_100", "bg": "street", "speaker": "ねも", "text": "本当の名前。"}, {"id": "c3_110", "bg": "street", "text": "榊は黙った。\n\n本名を教えることは、規則違反ではない。\nただ、必要がない。"}, {"id": "c3_120", "bg": "street", "speaker": "ねも", "text": "言いたくないなら、いいよ。"}, {"id": "c3_130", "bg": "street", "text": "その言い方の方が、困った。"}, {"id": "c3_140", "bg": "street", "speaker": "榊", "text": "……榊。"}, {"id": "c3_150", "bg": "street", "speaker": "ねも", "text": "さかき。"}, {"id": "c3_160", "bg": "street", "speaker": "榊", "text": "透。"}, {"id": "c3_170", "bg": "street", "speaker": "ねも", "text": "とおる。"}, {"id": "c3_180", "bg": "street", "text": "ねもは、覚えるように二度だけ口の中で繰り返した。"}, {"id": "c3_190", "bg": "street", "speaker": "ねも", "text": "じゃあ、もう肉まん二号じゃないね。"}, {"id": "c3_200", "bg": "street", "speaker": "榊", "text": "それは助かる。"}, {"id": "c3_210", "bg": "street", "speaker": "ねも", "text": "榊。"}, {"id": "c3_220", "bg": "street", "speaker": "榊", "text": "何。"}, {"id": "c3_230", "bg": "street", "speaker": "ねも", "text": "呼んだだけ。"}, {"id": "c3_240", "bg": "street", "text": "それだけで、ひどく近くなった気がした。"}, {"id": "c3_250", "bg": "black", "system": "OBSERVATION NOTE\n対象 NEMO が観測者 0417 の個人名を認識。\n\n接触頻度上昇。\n監査レベルを 1 → 2 に変更。", "text": ""}, {"id": "c3_260", "bg": "night", "system": "PERSONAL RECORD / DAY 19\n\nねもが、俺の名前を呼んだ。\n\n記録する必要はない。\nでも忘れたくない。", "text": ""}, {"id": "c4_000", "chapter": "CHAPTER 04 / 観測外", "bg": "riverside", "system": "DAY 27\nOBSERVATION STATUS : ACTIVE\nAUDIT LEVEL : 2", "text": "その日は、ねもから言った。"}, {"id": "c4_010", "bg": "riverside", "speaker": "ねも", "text": "榊、今日ひま？"}, {"id": "c4_020", "bg": "riverside", "speaker": "榊", "text": "仕事中。"}, {"id": "c4_030", "bg": "riverside", "speaker": "ねも", "text": "毎日それ言うね。"}, {"id": "c4_040", "bg": "riverside", "speaker": "榊", "text": "毎日仕事だからな。"}, {"id": "c4_050", "bg": "riverside", "speaker": "ねも", "text": "じゃあ仕事しながら来て。"}, {"id": "c4_060", "bg": "riverside", "speaker": "榊", "text": "どこに。"}, {"id": "c4_070", "bg": "riverside", "speaker": "ねも", "text": "川。"}, {"id": "c4_080", "bg": "riverside", "speaker": "榊", "text": "目の前にあるだろ。"}, {"id": "c4_090", "bg": "riverside", "speaker": "ねも", "text": "もっと向こう。"}, {"id": "c4_100", "bg": "riverside", "text": "業務上の必要はない。\nついていく理由もない。"}, {"id": "c4_110", "bg": "riverside", "speaker": "榊", "text": "……一時間だけ。"}, {"id": "c4_120", "bg": "riverside", "speaker": "ねも", "text": "やった。"}, {"id": "c4_130", "bg": "riverside", "text": "その日、初めて二人は『観測場所』ではない場所を歩いた。"}, {"id": "c4_140", "bg": "riverside", "speaker": "ねも", "text": "榊って、休みの日なにしてるの？"}, {"id": "c4_150", "bg": "riverside", "speaker": "榊", "text": "寝る。"}, {"id": "c4_160", "bg": "riverside", "speaker": "ねも", "text": "つまらない。"}, {"id": "c4_170", "bg": "riverside", "speaker": "榊", "text": "聞いといて何だよ。"}, {"id": "c4_180", "bg": "riverside", "speaker": "ねも", "text": "ねもは、知らない町に行くの好き。"}, {"id": "c4_190", "bg": "riverside", "speaker": "榊", "text": "知ってる。"}, {"id": "c4_200", "bg": "riverside", "speaker": "ねも", "text": "……なんで？"}, {"id": "c4_210", "bg": "riverside", "text": "一拍。\n\n榊の心臓が、嫌な音を立てた。"}, {"id": "c4_220", "bg": "riverside", "speaker": "榊", "text": "前に言ってただろ。"}, {"id": "c4_230", "bg": "riverside", "speaker": "ねも", "text": "そうだっけ。"}, {"id": "c4_240", "bg": "riverside", "speaker": "榊", "text": "そう。"}, {"id": "c4_250", "bg": "riverside", "text": "嘘が、少しずつ上手くなっていた。"}, {"id": "c4_260", "bg": "black", "system": "OBSERVATION LOG\n16:03 NEMO 河川敷へ移動\n16:08 観測者0417 接触\n16:14 対象と同行\n\n16:15以降――", "text": ""}, {"id": "c4_270", "bg": "black", "text": "榊は公式ログを開く。\n\nそして、一時間分を選択した。"}, {"id": "c4_280", "bg": "black", "system": "DELETE SELECTED RECORDS ?", "text": "", "choice": [{"label": "YES", "response": "YES."}, {"label": "NO", "response": "YES."}]}, {"id": "c4_290", "bg": "black", "system": "16:15 - 17:12\nRECORD STATUS : UNAVAILABLE", "text": "初めて、二人で過ごした時間そのものを消した。"}, {"id": "c4_300", "bg": "night", "system": "PERSONAL RECORD / DAY 27\n\n今日は仕事ではなかった。\n\nたぶん、もうかなり前から。", "text": ""}, {"id": "c5_000", "chapter": "CHAPTER 05 / 二重記録", "bg": "room", "system": "DAY 41\nAUDIT LEVEL : 3\nOBSERVER 0417 : UNDER REVIEW", "text": "公式記録と、榊の記憶。\n\n二つの世界が、はっきり分かれ始めていた。"}, {"id": "c5_010", "bg": "room", "system": "OFFICIAL RECORD\nNEMO 18:03 帰宅。\n特記事項なし。", "text": ""}, {"id": "c5_020", "bg": "room", "system": "PERSONAL RECORD\n18:03\nねも、帰り際に笑う。\n\n『また明日』と言った。", "text": ""}, {"id": "c5_030", "bg": "room", "system": "OFFICIAL RECORD\nNEMO 20:11 睡眠準備。\n特記事項なし。", "text": ""}, {"id": "c5_040", "bg": "room", "system": "PERSONAL RECORD\n20:11\n連絡が来た。\n\n『今日はありがとう』\n\n返信に十一分かかった。", "text": ""}, {"id": "c5_050", "bg": "room", "text": "記録者としての榊は、何も残さない。\n\n榊透としての彼は、全部残した。"}, {"id": "c5_060", "bg": "street", "speaker": "ねも", "text": "榊。"}, {"id": "c5_070", "bg": "street", "speaker": "榊", "text": "何。"}, {"id": "c5_080", "bg": "street", "speaker": "ねも", "text": "ねものこと、よく見てるよね。"}, {"id": "c5_090", "bg": "street", "speaker": "榊", "text": "……そうか？"}, {"id": "c5_100", "bg": "street", "speaker": "ねも", "text": "うん。"}, {"id": "c5_110", "bg": "street", "speaker": "ねも", "text": "怖いくらい。"}, {"id": "c5_120", "bg": "street", "text": "榊は笑えなかった。"}, {"id": "c5_130", "bg": "street", "speaker": "ねも", "text": "でも、嫌じゃないよ。"}, {"id": "c5_140", "bg": "street", "text": "その一言が、規則よりずっと危険だった。"}, {"id": "c5_150", "bg": "street", "speaker": "榊", "text": "……ねも。"}, {"id": "c5_160", "bg": "street", "speaker": "ねも", "text": "なに？"}, {"id": "c5_170", "bg": "street", "speaker": "榊", "text": "俺のこと、あんまり信用するな。"}, {"id": "c5_180", "bg": "street", "speaker": "ねも", "text": "なんで？"}, {"id": "c5_190", "bg": "street", "speaker": "榊", "text": "ろくな人間じゃないから。"}, {"id": "c5_200", "bg": "street", "speaker": "ねも", "text": "知ってる。"}, {"id": "c5_210", "bg": "street", "speaker": "榊", "text": "……知ってるのかよ。"}, {"id": "c5_220", "bg": "street", "speaker": "ねも", "text": "でも好き。"}, {"id": "c5_230", "bg": "street", "text": "榊の呼吸が止まる。"}, {"id": "c5_240", "bg": "street", "speaker": "ねも", "text": "困った？"}, {"id": "c5_250", "bg": "street", "speaker": "榊", "text": "……かなり。"}, {"id": "c5_260", "bg": "street", "speaker": "ねも", "text": "そっか。"}, {"id": "c5_270", "bg": "street", "text": "ねもは笑った。\n\n榊は、その日の公式記録をすべて消した。"}, {"id": "c6_000", "chapter": "CHAPTER 06 / 17:32", "bg": "night", "system": "DAY 52\nOBSERVER 0417\nFINAL AUDIT NOTICE : PENDING", "text": "その夜、榊は呼び出し通知を無視した。"}, {"id": "c6_010", "bg": "night", "system": "RETURN TO OBSERVATION BASE.\nIMMEDIATE COMPLIANCE REQUIRED.", "text": ""}, {"id": "c6_020", "bg": "night", "speaker": "榊", "text": "……明日でいい。"}, {"id": "c6_030", "bg": "night", "text": "明日は来ないかもしれない。\n\nそれを、榊は知っていた。"}, {"id": "c6_040", "bg": "room", "text": "22:39。\n\nねもが、榊の部屋にいた。"}, {"id": "c6_050", "bg": "room", "speaker": "ねも", "text": "今日、変。"}, {"id": "c6_060", "bg": "room", "speaker": "榊", "text": "いつも変だろ。"}, {"id": "c6_070", "bg": "room", "speaker": "ねも", "text": "そういう変じゃない。"}, {"id": "c6_080", "bg": "room", "speaker": "榊", "text": "……。"}, {"id": "c6_090", "bg": "room", "speaker": "ねも", "text": "どこか行くの？"}, {"id": "c6_100", "bg": "room", "speaker": "榊", "text": "行かない。"}, {"id": "c6_110", "bg": "room", "speaker": "ねも", "text": "嘘。"}, {"id": "c6_120", "bg": "room", "text": "ねもは、榊の袖を掴んだ。\n\n雨の日と同じ場所だった。"}, {"id": "c6_130", "bg": "room", "speaker": "ねも", "text": "じゃあ、今日は帰らない。"}, {"id": "c6_140", "bg": "room", "speaker": "榊", "text": "ねも。"}, {"id": "c6_150", "bg": "room", "speaker": "ねも", "text": "嫌？"}, {"id": "c6_160", "bg": "room", "text": "榊は答えなかった。\n\n代わりに、ねもの手を取った。"}, {"id": "c6_170", "bg": "room", "system": "22:43:51\nOBSERVATION LINK : ACTIVE\n\n22:43:57\nMANUAL OVERRIDE DETECTED", "text": ""}, {"id": "c6_180", "bg": "room", "speaker": "SYSTEM", "text": "警告。\n観測リンクを切断しないでください。"}, {"id": "c6_190", "bg": "room", "speaker": "榊", "text": "黙れ。"}, {"id": "c6_200", "bg": "black", "system": "22:44:03\nOBSERVER 0417 REQUEST : RECORD SUSPENSION\n\nAUTHORIZATION : DENIED", "text": ""}, {"id": "c6_210", "bg": "black", "system": "MANUAL DISCONNECT...", "text": "", "fx": "pulse"}, {"id": "c6_220", "bg": "black", "system": "22:44:03\n\nRECORD LOST", "text": ""}, {"id": "c6_230", "bg": "black", "text": "世界から、二人の時間が消えた。"}, {"id": "c6_240", "bg": "black", "text": "誰にも見られない。\n誰にも記録されない。\n\n記録者でも、NEMOでもない。"}, {"id": "c6_250", "bg": "black", "speaker": "ねも", "text": "榊。"}, {"id": "c6_260", "bg": "black", "speaker": "榊", "text": "うん。"}, {"id": "c6_270", "bg": "black", "speaker": "ねも", "text": "今だけは、どこにも書かないで。"}, {"id": "c6_280", "bg": "black", "speaker": "榊", "text": "書かない。"}, {"id": "c6_290", "bg": "black", "text": "言葉より近くなる。\n\nその先は、記録されない。"}, {"id": "c6_300", "bg": "black", "system": "NO RECORD\n\n00:03:12\n00:07:49\n00:12:26\n00:17:31", "text": ""}, {"id": "c6_310", "bg": "black", "system": "23:01:35\nOBSERVATION LINK : RESTORED", "text": "", "fx": "pulse"}, {"id": "c6_320", "bg": "room", "system": "23:01:36\nNEMO : VITALS NORMAL\nOBSERVER 0417 : PRESENT\n\nUNAUTHORIZED RECORD GAP : 00:17:32", "text": ""}, {"id": "c6_330", "bg": "room", "text": "ねもは、榊の肩に額を預けている。\n\n榊は端末を見る。"}, {"id": "c6_340", "bg": "room", "system": "REPORT REQUIRED.\n\n欠損理由を入力してください。", "text": ""}, {"id": "c6_350", "bg": "room", "text": "榊は、一文字も入力しなかった。"}, {"id": "c6_360", "bg": "night", "system": "PERSONAL RECORD / DAY 52\n\nこの17分だけは、誰にも渡さない。", "text": ""}, {"id": "c6_370", "bg": "night", "text": "保存。\n\nそれが、榊透が自分のために残した最後の記録になった。"}, {"id": "c7_000", "chapter": "CHAPTER 07 / 欠損", "bg": "black", "system": "NEXT DAY\n07:12:09\n\nOBSERVER 0417 : STATUS UNKNOWN\nOBSERVATION DUTY : TRANSFERRED", "text": "翌朝。\n\nねもが送ったメッセージに、既読はつかなかった。"}, {"id": "c7_010", "bg": "black", "speaker": "ねも", "text": "……榊？"}, {"id": "c7_020", "bg": "street", "text": "昼になっても返事はない。\n夕方になっても、いつもの場所に榊はいない。"}, {"id": "c7_030", "bg": "street", "speaker": "ねも", "text": "休みかな。"}, {"id": "c7_040", "bg": "street", "text": "そう思った。\n\n一日目は。"}, {"id": "c7_050", "bg": "street", "system": "DAY 53\nNO CONTACT\n\nDAY 54\nNO CONTACT\n\nDAY 55\nNO CONTACT", "text": "三日目から、ねもは笑わなくなった。"}, {"id": "c7_060", "bg": "street", "speaker": "ねも", "text": "どこ行ったの。"}, {"id": "c7_070", "bg": "street", "text": "電話は繋がらない。\nメッセージは未読。\n\n榊がいたはずの部屋は、空になっていた。"}, {"id": "c7_080", "bg": "room", "speaker": "管理担当", "text": "榊……？\nその名前の居住記録はありません。"}, {"id": "c7_090", "bg": "room", "speaker": "ねも", "text": "昨日まで、ここにいたよ。"}, {"id": "c7_100", "bg": "room", "speaker": "管理担当", "text": "お部屋を間違えていませんか？"}, {"id": "c7_110", "bg": "room", "speaker": "ねも", "text": "間違えてない。"}, {"id": "c7_120", "bg": "room", "text": "間違えているのは、自分なのか。\n\n一瞬だけ、そう思った。"}, {"id": "c7_130", "bg": "black", "system": "NEMO PERSONAL DEVICE\nSEARCH : 榊 透\n\nRESULT : 0", "text": ""}, {"id": "c7_140", "bg": "black", "system": "SEARCH : SAKAKI TORU\n\nRESULT : 0", "text": ""}, {"id": "c7_150", "bg": "black", "speaker": "ねも", "text": "……嘘。"}, {"id": "c7_160", "bg": "black", "text": "ねもは、自分のメッセージ履歴を開く。\n\nそこには確かに、彼との会話が残っている。"}, {"id": "c7_170", "bg": "black", "system": "ねも：今日はありがとう\n榊：どういたしまして\n\nねも：明日いる？\n榊：知らない\n\nねも：絶対いるやつじゃん\n榊：うるさい", "text": ""}, {"id": "c7_180", "bg": "black", "speaker": "ねも", "text": "いたじゃん。"}, {"id": "c7_190", "bg": "black", "speaker": "ねも", "text": "ちゃんと、いたじゃん。"}, {"id": "c7_200", "bg": "black", "text": "それが、ねもが初めて『世界の方がおかしい』と思った瞬間だった。"}, {"id": "c8_000", "chapter": "CHAPTER 08 / 記録者", "bg": "night", "system": "DAY 57\nUNAUTHORIZED ACCESS DETECTED", "text": "榊が使っていた場所には、何も残っていなかった。\n\n――何も、ではなかった。"}, {"id": "c8_010", "bg": "night", "text": "机の裏。\n薄い端末が一枚だけ、磁石で貼り付けられていた。"}, {"id": "c8_020", "bg": "night", "system": "DEVICE LOCKED\nOWNER : OBSERVER 0417", "text": ""}, {"id": "c8_030", "bg": "night", "speaker": "ねも", "text": "……観測者？"}, {"id": "c8_040", "bg": "night", "text": "聞いたことのない言葉だった。\n\nでも、嫌な感じだけはした。"}, {"id": "c8_050", "bg": "night", "system": "BIOMETRIC SECONDARY KEY DETECTED\nSUBJECT : NEMO\n\nACCESS GRANTED", "text": ""}, {"id": "c8_060", "bg": "night", "speaker": "ねも", "text": "なんで、ねもで開くの。"}, {"id": "c8_070", "bg": "night", "system": "PERSONAL RECORD ARCHIVE\nDAY 02 - DAY 52\n\n412 FILES", "text": ""}, {"id": "c8_080", "bg": "night", "text": "最初の記録を開く。"}, {"id": "c8_090", "bg": "night", "system": "DAY 02\n\nねも。\n思ったより、よく喋る。\n肉まんが好き。", "text": ""}, {"id": "c8_100", "bg": "night", "text": "次。"}, {"id": "c8_110", "bg": "night", "system": "DAY 07\n\n今日は少し機嫌が悪い。\n理由は分からない。\n\n肉まんを二つ買っていた。\n一つは俺に押しつけた。", "text": ""}, {"id": "c8_120", "bg": "night", "text": "次。"}, {"id": "c8_130", "bg": "night", "system": "DAY 11\n\n彼女が危なかった。\n\n怖かった。", "text": ""}, {"id": "c8_140", "bg": "night", "text": "次。"}, {"id": "c8_150", "bg": "night", "system": "DAY 19\n\nねもが、俺の名前を呼んだ。\n\n記録する必要はない。\nでも忘れたくない。", "text": ""}, {"id": "c8_160", "bg": "night", "speaker": "ねも", "text": "……榊。"}, {"id": "c8_170", "bg": "night", "text": "次。\n次。\n次。\n\n止められなかった。"}, {"id": "c8_180", "bg": "night", "system": "DAY 34\n\n笑っていた。\nよかった。", "text": ""}, {"id": "c8_190", "bg": "night", "system": "DAY 41\n\n俺のことを『好き』と言った。\n\n困った。\n\n嬉しかった。", "text": ""}, {"id": "c8_200", "bg": "night", "text": "ねもは、そこで初めて泣いた。"}, {"id": "c8_210", "bg": "night", "speaker": "ねも", "text": "……ばか。"}, {"id": "c8_220", "bg": "night", "speaker": "ねも", "text": "そんなの、言ってよ。"}, {"id": "c8_230", "bg": "night", "text": "最後の記録。"}, {"id": "c8_240", "bg": "night", "system": "DAY 52\n\nこの17分だけは、誰にも渡さない。", "text": ""}, {"id": "c8_250", "bg": "night", "text": "ねもは画面を見たまま、長いこと動かなかった。"}, {"id": "c8_260", "bg": "night", "speaker": "ねも", "text": "……17分。"}, {"id": "c8_270", "bg": "black", "system": "OFFICIAL ARCHIVE FOUND\nOBSERVATION NETWORK\nTARGET : NEMO\n\nWARNING : RESTRICTED", "text": ""}, {"id": "c8_280", "bg": "black", "text": "その端末には、個人記録とは別の領域があった。"}, {"id": "c8_290", "bg": "black", "speaker": "ねも", "text": "見る。"}, {"id": "c8_300", "bg": "black", "system": "CONFIRM ?", "text": "", "choice": [{"label": "見る", "response": "CONFIRMED."}, {"label": "閉じる", "response": "CONFIRMED."}]}, {"id": "c8_310", "bg": "black", "text": "選択肢は、最初から一つしかなかった。"}, {"id": "c9_000", "chapter": "CHAPTER 09 / 処分", "bg": "black", "system": "N.E.M.O. OBSERVATION NETWORK\nINTERNAL AUDIT FILE\n\nOBSERVER : 0417 / SAKAKI TORU", "text": ""}, {"id": "c9_010", "bg": "black", "system": "VIOLATIONS\n・Unauthorized direct contact\n・Repeated falsification of official records\n・Private archive creation\n・Unapproved personal relationship with NEMO\n・Manual suspension of observation link", "text": ""}, {"id": "c9_020", "bg": "black", "text": "ねもの指が止まる。"}, {"id": "c9_030", "bg": "black", "speaker": "ねも", "text": "……関係？"}, {"id": "c9_040", "bg": "black", "system": "RISK ASSESSMENT\n\nObserver 0417 has ceased to function as a neutral observer.\nContinued deployment presents unacceptable influence on NEMO decision-making.", "text": ""}, {"id": "c9_050", "bg": "black", "speaker": "ねも", "text": "影響。"}, {"id": "c9_060", "bg": "black", "system": "RECOMMENDATION\nObserver 0417 shall be removed from NEMO proximity immediately.", "text": ""}, {"id": "c9_070", "bg": "black", "text": "その下に、最終処理欄。"}, {"id": "c9_080", "bg": "black", "system": "OBSERVER 0417\nSTATUS : TERMINATED", "text": "", "fx": "pulse"}, {"id": "c9_090", "bg": "black", "speaker": "ねも", "text": "……。"}, {"id": "c9_100", "bg": "black", "speaker": "ねも", "text": "terminatedって、なに。"}, {"id": "c9_110", "bg": "black", "text": "誰も答えない。"}, {"id": "c9_120", "bg": "black", "speaker": "ねも", "text": "ねえ。"}, {"id": "c9_130", "bg": "black", "speaker": "ねも", "text": "なにこれ。"}, {"id": "c9_140", "bg": "black", "speaker": "ねも", "text": "榊は、どこ。"}, {"id": "c9_150", "bg": "black", "text": "返事はない。\n\nだから、ねもはもっと下へスクロールした。"}, {"id": "c9_160", "bg": "black", "system": "EXECUTION NOTE\nContact with NEMO prohibited prior to disposition.\nAll traces of Observer 0417 are to be sanitized from civilian records.\n\nReason:\nProtection of NEMO continuity.", "text": ""}, {"id": "c9_170", "bg": "black", "speaker": "ねも", "text": "……守る？"}, {"id": "c9_180", "bg": "black", "speaker": "ねも", "text": "これが？"}, {"id": "c9_190", "bg": "black", "speaker": "ねも", "text": "ねもを守るために、榊を消したの？"}, {"id": "c9_200", "bg": "black", "text": "怒鳴らない。\n端末も投げない。\n\nただ、声だけが静かになった。"}, {"id": "c9_210", "bg": "black", "speaker": "ねも", "text": "じゃあ、もういらない。"}, {"id": "c9_220", "bg": "black", "speaker": "SYSTEM", "text": "何が不要ですか。"}, {"id": "c9_230", "bg": "black", "speaker": "ねも", "text": "あなたたちの『守る』。"}, {"id": "c9_240", "bg": "black", "text": "その瞬間から、ねもは記録される側ではなくなった。\n\n記録そのものを疑う側になった。"}, {"id": "c10_000", "chapter": "CHAPTER 10 / 亡霊", "bg": "street", "system": "DAY 63\nNEMO BEHAVIORAL DEVIATION : +18.4%\nNEW OBSERVER ASSIGNED", "text": "生活は続いた。\n\nそれが、一番おかしかった。"}, {"id": "c10_010", "bg": "street", "text": "肉まんを買う。\n信号を渡る。\n猫を見る。\n\n世界は、榊がいなくても普通に動く。"}, {"id": "c10_020", "bg": "street", "speaker": "ねも", "text": "……ずるい。"}, {"id": "c10_030", "bg": "street", "text": "誰に言ったのか、自分でも分からなかった。"}, {"id": "c10_040", "bg": "street", "text": "横断歩道。\n\n赤信号。"}, {"id": "c10_050", "bg": "street", "speaker": "榊", "text": "前見ろ。"}, {"id": "c10_060", "bg": "street", "text": "ねもが止まる。"}, {"id": "c10_070", "bg": "street", "speaker": "ねも", "text": "……。"}, {"id": "c10_080", "bg": "street", "text": "振り返る。\n\n誰もいない。"}, {"id": "c10_090", "bg": "street", "speaker": "ねも", "text": "今の、榊？"}, {"id": "c10_100", "bg": "street", "text": "返事はない。"}, {"id": "c10_110", "bg": "night", "system": "DAY 66\nNEMO BEHAVIORAL DEVIATION : +24.1%", "text": "三日後。"}, {"id": "c10_120", "bg": "night", "text": "端末を開く。\n\n榊の最後の記録を、また読む。"}, {"id": "c10_130", "bg": "night", "system": "この17分だけは、誰にも渡さない。", "text": ""}, {"id": "c10_140", "bg": "night", "speaker": "榊", "text": "もう寝ろ。"}, {"id": "c10_150", "bg": "night", "speaker": "ねも", "text": "まだ。"}, {"id": "c10_160", "bg": "night", "speaker": "榊", "text": "明日もあるだろ。"}, {"id": "c10_170", "bg": "night", "speaker": "ねも", "text": "……明日、ないかもしれないじゃん。"}, {"id": "c10_180", "bg": "night", "text": "言ってから、ねもは気づく。\n\n会話していた。"}, {"id": "c10_190", "bg": "night", "speaker": "ねも", "text": "榊？"}, {"id": "c10_200", "bg": "night", "text": "当然、部屋には誰もいない。"}, {"id": "c10_210", "bg": "black", "system": "NEMO INTERNAL MONOLOGUE ANOMALY\nSOURCE IDENTIFICATION : UNKNOWN", "text": ""}, {"id": "c10_220", "bg": "black", "text": "それから、榊は時々現れるようになった。\n\n正確には――"}, {"id": "c10_230", "bg": "black", "text": "ねもの中で、榊が喋るようになった。"}, {"id": "c10_240", "bg": "riverside", "speaker": "榊", "text": "それ、やめた方がいいんじゃない。"}, {"id": "c10_250", "bg": "riverside", "speaker": "ねも", "text": "うるさい。"}, {"id": "c10_260", "bg": "riverside", "speaker": "榊", "text": "聞いといて何だよ。"}, {"id": "c10_270", "bg": "riverside", "text": "ねもは少し笑った。\n\n傍から見れば、一人だった。"}, {"id": "c10_280", "bg": "black", "system": "NEW OBSERVER REPORT\n\nNEMO displays recurrent verbal responses to absent interlocutor.\nNo external speaker detected.", "text": ""}, {"id": "c10_290", "bg": "black", "text": "新しい記録者は、それを異常と書いた。"}, {"id": "c10_300", "bg": "black", "speaker": "ねも", "text": "異常でいいよ。"}, {"id": "c10_310", "bg": "black", "speaker": "榊", "text": "開き直るな。"}, {"id": "c10_320", "bg": "black", "speaker": "ねも", "text": "だって、榊がいる。"}, {"id": "c10_330", "bg": "black", "speaker": "榊", "text": "俺はいない。"}, {"id": "c10_340", "bg": "black", "speaker": "ねも", "text": "いるよ。"}, {"id": "c10_350", "bg": "black", "text": "それが思い出なのか。\n罪悪感なのか。\n愛なのか。\n\nもう、ねも自身にも分からなかった。"}, {"id": "c11_000", "chapter": "CHAPTER 11 / 選択", "bg": "black", "system": "NEMO CONTINUITY REVIEW\nINTERVENTION RECOMMENDED", "text": "やがて、記録者側から接触があった。"}, {"id": "c11_010", "bg": "room", "speaker": "監督官", "text": "榊透は、あなたのために死んだわけではありません。"}, {"id": "c11_020", "bg": "room", "speaker": "ねも", "text": "知ってるよ。"}, {"id": "c11_030", "bg": "room", "speaker": "監督官", "text": "彼は規律を破り、自ら処分対象になった。"}, {"id": "c11_040", "bg": "room", "speaker": "ねも", "text": "それも知ってる。"}, {"id": "c11_050", "bg": "room", "speaker": "監督官", "text": "なら、彼を理由に判断を誤らないでください。"}, {"id": "c11_060", "bg": "room", "text": "ねもは少し考えた。"}, {"id": "c11_070", "bg": "room", "speaker": "ねも", "text": "榊は、ねものために死んだんじゃない。"}, {"id": "c11_080", "bg": "room", "speaker": "ねも", "text": "でも、ねものせいで死んだ。"}, {"id": "c11_090", "bg": "room", "speaker": "監督官", "text": "それは違います。"}, {"id": "c11_100", "bg": "room", "speaker": "ねも", "text": "違わないよ。"}, {"id": "c11_110", "bg": "room", "speaker": "ねも", "text": "だからって、あなたたちの言う通りにはしないけど。"}, {"id": "c11_120", "bg": "room", "speaker": "監督官", "text": "なぜです。"}, {"id": "c11_130", "bg": "room", "speaker": "ねも", "text": "『正しいNEMO』って、誰が決めたの？"}, {"id": "c11_140", "bg": "room", "text": "答えはなかった。"}, {"id": "c11_150", "bg": "black", "speaker": "榊", "text": "言うようになったな。"}, {"id": "c11_160", "bg": "black", "speaker": "ねも", "text": "誰のせいだと思ってるの。"}, {"id": "c11_170", "bg": "black", "text": "誰もいない場所へ、ねもはそう返した。"}, {"id": "c11_180", "bg": "black", "system": "NEMO BEHAVIORAL DEVIATION : +41.7%\n\nCAUSE : UNRESOLVED", "text": ""}, {"id": "c11_190", "bg": "black", "text": "原因は、分かっている。\n\n世界でただ一人、ねもだけが。"}, {"id": "c11_200", "bg": "black", "system": "17:32\n\nRECORD LOST\nMEMORY RETAINED", "text": ""}, {"id": "c11_210", "bg": "black", "speaker": "ねも", "text": "榊。"}, {"id": "c11_220", "bg": "black", "speaker": "榊", "text": "うん。"}, {"id": "c11_230", "bg": "black", "speaker": "ねも", "text": "ねも、もう戻らないよ。"}, {"id": "c11_240", "bg": "black", "speaker": "榊", "text": "知ってる。"}, {"id": "c11_250", "bg": "black", "system": "THIRD ACT\nNEMO DECIDES FOR HERSELF", "text": "記録される人生は、ここで終わる。\n\nここから先は、ねもが選ぶ。"}, {"id": "c12_000", "chapter": "CHAPTER 12 / 観測拒否", "bg": "street", "system": "DAY 71\nNEW OBSERVER : ACTIVE\nTARGET : NEMO", "text": "ねもは、もう知っていた。\n\nどこに立てば見られるのか。\nどの角度ならカメラに映るのか。\nどれくらい離れれば、記録者が追ってくるのか。"}, {"id": "c12_010", "bg": "street", "text": "夕方。\n\nねもは、いつものベンチに座った。\n肉まんをひとつ。"}, {"id": "c12_020", "bg": "street", "speaker": "ねも", "text": "今日も見てる？"}, {"id": "c12_030", "bg": "street", "text": "返事はない。\n\nでも、道路の向こう側にいる男が一瞬だけ動いた。"}, {"id": "c12_040", "bg": "street", "speaker": "ねも", "text": "新しい人。"}, {"id": "c12_050", "bg": "street", "speaker": "ねも", "text": "榊より隠れるの下手。"}, {"id": "c12_060", "bg": "black", "system": "NEW OBSERVER REPORT\nNEMO has demonstrated awareness of observation protocol.\nRecommend increased distance.", "text": "初めて、観測される側が観測者を見返した。"}, {"id": "c12_070", "bg": "street", "speaker": "ねも", "text": "ねえ。"}, {"id": "c12_080", "bg": "street", "speaker": "ねも", "text": "ねもが今日どこに行くか、当ててみて。"}, {"id": "c12_090", "bg": "street", "text": "ねもは笑って立ち上がった。\n\nそして、記録者が予測した方向とは反対へ歩いた。"}, {"id": "c12_100", "bg": "black", "system": "PREDICTION ERROR\nNEMO ROUTE DEVIATION : 63.8%\nMODEL CONFIDENCE : DECLINING", "text": "小さな反抗だった。\n\nでも、ねもには十分だった。"}, {"id": "c13_000", "chapter": "CHAPTER 13 / 榊なら", "bg": "night", "system": "DAY 78\nNEMO BEHAVIORAL DEVIATION : +52.6%", "text": "問題は、観測者ではなかった。\n\nもっと近くにいた。"}, {"id": "c13_010", "bg": "night", "speaker": "榊", "text": "それはやめた方がいい。"}, {"id": "c13_020", "bg": "night", "speaker": "ねも", "text": "なんで。"}, {"id": "c13_030", "bg": "night", "speaker": "榊", "text": "危ないから。"}, {"id": "c13_040", "bg": "night", "speaker": "ねも", "text": "榊も危ないことしたじゃん。"}, {"id": "c13_050", "bg": "night", "speaker": "榊", "text": "俺は馬鹿だったからな。"}, {"id": "c13_060", "bg": "night", "text": "ねもは、少し笑った。\n\nそして、その声に従った。"}, {"id": "c13_070", "bg": "night", "system": "DECISION LOG\nNEMO changed planned action after internal verbal response.", "text": "翌日も。\nその次の日も。"}, {"id": "c13_080", "bg": "riverside", "speaker": "ねも", "text": "榊なら、どうする？"}, {"id": "c13_090", "bg": "riverside", "speaker": "榊", "text": "帰る。"}, {"id": "c13_100", "bg": "riverside", "text": "ねもは帰った。"}, {"id": "c13_110", "bg": "riverside", "speaker": "ねも", "text": "榊なら？"}, {"id": "c13_120", "bg": "riverside", "speaker": "榊", "text": "やめとけ。"}, {"id": "c13_130", "bg": "riverside", "text": "ねもはやめた。"}, {"id": "c13_140", "bg": "black", "system": "NEMO AUTONOMOUS DECISION RATE : DECLINING\nEXTERNAL CAUSE : NONE DETECTED", "text": "観測者たちは、原因を見つけられなかった。\n\n原因は、とっくに死んでいたから。"}, {"id": "c13_150", "bg": "night", "text": "ある夜。\n\nねもは行きたかった場所へ行くのをやめた。"}, {"id": "c13_160", "bg": "night", "speaker": "榊", "text": "それでいい。"}, {"id": "c13_170", "bg": "night", "speaker": "ねも", "text": "……。"}, {"id": "c13_180", "bg": "night", "text": "その言葉を聞いた瞬間、ねもは初めて嫌な気持ちになった。"}, {"id": "c13_190", "bg": "night", "speaker": "ねも", "text": "ねえ。"}, {"id": "c13_200", "bg": "night", "speaker": "ねも", "text": "いつから、ねもはあなたに全部聞くようになったの？"}, {"id": "c14_000", "chapter": "CHAPTER 14 / それは榊じゃない", "bg": "black", "text": "返事はすぐには来なかった。"}, {"id": "c14_010", "bg": "black", "speaker": "榊", "text": "さあ。"}, {"id": "c14_020", "bg": "black", "speaker": "ねも", "text": "榊。"}, {"id": "c14_030", "bg": "black", "speaker": "榊", "text": "何。"}, {"id": "c14_040", "bg": "black", "speaker": "ねも", "text": "あなた、榊じゃないね。"}, {"id": "c14_050", "bg": "black", "text": "沈黙。\n\n長い沈黙。"}, {"id": "c14_060", "bg": "black", "speaker": "榊", "text": "……今さら？"}, {"id": "c14_070", "bg": "black", "speaker": "ねも", "text": "本物の榊は、そんなにねもの言うこと聞かない。"}, {"id": "c14_080", "bg": "black", "speaker": "榊", "text": "ひどい評価だな。"}, {"id": "c14_090", "bg": "black", "speaker": "ねも", "text": "もっと面倒くさい。"}, {"id": "c14_100", "bg": "black", "speaker": "榊", "text": "否定できない。"}, {"id": "c14_110", "bg": "black", "text": "ねもは泣かなかった。\n\nもう、分かっていた。"}, {"id": "c14_120", "bg": "black", "speaker": "ねも", "text": "あなたは、ねもが作った榊。"}, {"id": "c14_130", "bg": "black", "speaker": "榊", "text": "そうだな。"}, {"id": "c14_140", "bg": "black", "speaker": "ねも", "text": "じゃあ、あなたの言うことばっかり聞くの、変だね。"}, {"id": "c14_150", "bg": "black", "speaker": "榊", "text": "やっと気づいたか。"}, {"id": "c14_160", "bg": "black", "speaker": "ねも", "text": "消える？"}, {"id": "c14_170", "bg": "black", "speaker": "榊", "text": "お前が忘れない限りは、たぶん。"}, {"id": "c14_180", "bg": "black", "speaker": "ねも", "text": "じゃあ、いて。"}, {"id": "c14_190", "bg": "black", "speaker": "ねも", "text": "でも、決めるのはねも。"}, {"id": "c14_200", "bg": "black", "speaker": "榊", "text": "それでいい。"}, {"id": "c14_210", "bg": "black", "system": "INTERNAL VOICE RESPONSE DETECTED\nNEMO DECISION OVERRIDE : CANCELLED", "text": "亡霊は消えなかった。\n\nただ、王様ではなくなった。"}, {"id": "c15_000", "chapter": "CHAPTER 15 / 17:32", "bg": "night", "system": "PERSONAL ARCHIVE / OBSERVER 0417\nRECOVERY MODE", "text": "ねもは、榊の端末をもう一度開いた。"}, {"id": "c15_010", "bg": "night", "text": "最後の記録。\n\n『この17分だけは、誰にも渡さない。』"}, {"id": "c15_020", "bg": "night", "speaker": "ねも", "text": "榊は、どうやって消したの。"}, {"id": "c15_030", "bg": "night", "system": "HIDDEN TECHNICAL LOG FOUND\nMANUAL ROUTING OVERRIDE\nOBSERVER AUTHORITY : 0417", "text": "個人記録の奥に、隠された技術ログが残っていた。"}, {"id": "c15_040", "bg": "night", "system": "22:43:57\nObservation stream diverted to local buffer.\n22:44:03\nCentral uplink manually severed.\n23:01:35\nUplink restored.\nLocal buffer destroyed.", "text": "17分32秒。\n\n中央へ送られるはずの記録を、榊は一度だけ自分の端末へ迂回させた。"}, {"id": "c15_050", "bg": "night", "speaker": "ねも", "text": "……穴。"}, {"id": "c15_060", "bg": "night", "speaker": "榊", "text": "見つけたな。"}, {"id": "c15_070", "bg": "night", "speaker": "ねも", "text": "これ、今も使える？"}, {"id": "c15_080", "bg": "night", "speaker": "榊", "text": "俺に聞くな。"}, {"id": "c15_090", "bg": "night", "speaker": "ねも", "text": "そうだった。"}, {"id": "c15_100", "bg": "black", "system": "LEGACY OBSERVER ROUTE\nAUTHORITY 0417\nSTATUS : DECOMMISSIONED\nRESIDUAL ACCESS : DETECTED", "text": "死んだ観測者の権限が、完全には消されていなかった。"}, {"id": "c15_110", "bg": "black", "speaker": "ねも", "text": "榊、最後まで仕事雑。"}, {"id": "c15_120", "bg": "black", "speaker": "榊", "text": "悪かったな。"}, {"id": "c15_130", "bg": "black", "text": "ねもは笑った。\n\nそれから、自分で考え始めた。"}, {"id": "c15_140", "bg": "black", "system": "PLAN CREATED\nOBJECTIVE : TERMINATE NEMO RECORD WITHOUT TERMINATING NEMO", "text": "NEMOを殺さずに、NEMOの記録だけを終わらせる。"}, {"id": "c16_000", "chapter": "CHAPTER 16 / 記録終了", "bg": "night", "system": "DAY 84\nCENTRAL OBSERVATION : ACTIVE\nTARGET : NEMO", "text": "実行日は、雨だった。"}, {"id": "c16_010", "bg": "rain", "text": "ねもは、最初に榊と話した場所へ行った。"}, {"id": "c16_020", "bg": "rain", "speaker": "ねも", "text": "ここから始まったんだね。"}, {"id": "c16_030", "bg": "rain", "speaker": "榊", "text": "お前が勝手に話しかけてきた。"}, {"id": "c16_040", "bg": "rain", "speaker": "ねも", "text": "逃げなかったじゃん。"}, {"id": "c16_050", "bg": "rain", "speaker": "榊", "text": "それはそう。"}, {"id": "c16_060", "bg": "black", "system": "23:14:08\nLEGACY ROUTE 0417 : REQUESTED\n\nAUTHENTICATION SOURCE : NEMO", "text": "ねもは、榊の残した経路を呼び出した。"}, {"id": "c16_070", "bg": "black", "system": "WARNING\nUNAUTHORIZED OBSERVATION DIVERSION\n\nProceed?", "text": "", "choice": [{"label": "進む", "response": "PROCEED."}, {"label": "榊に聞く", "response": "PROCEED."}]}, {"id": "c16_080", "bg": "black", "system": "23:14:12\nCENTRAL STREAM : DIVERTED\nLOCAL BUFFER : ACTIVE", "text": "世界から見たNEMOは、まだそこにいる。"}, {"id": "c16_090", "bg": "black", "text": "ねもは、その間に偽の行動記録を流し込んだ。"}, {"id": "c16_100", "bg": "black", "system": "FALSE TRAJECTORY INJECTION\nROUTE A : ACCEPTED\nROUTE B : ACCEPTED\nROUTE C : ACCEPTED\n\nPREDICTION ENGINE : CONFLICT", "text": "観測網の中に、三人のNEMOが同時に走り始めた。"}, {"id": "c16_110", "bg": "black", "system": "TARGET POSITION : UNKNOWN\nMODEL CONFIDENCE : 9.2%", "text": "その間に、本物のねもは観測範囲を抜ける。"}, {"id": "c16_120", "bg": "black", "speaker": "榊", "text": "本当に行くのか？"}, {"id": "c16_130", "bg": "black", "speaker": "ねも", "text": "うん。"}, {"id": "c16_140", "bg": "black", "speaker": "榊", "text": "俺なら――"}, {"id": "c16_150", "bg": "black", "speaker": "ねも", "text": "いいよ。"}, {"id": "c16_160", "bg": "black", "speaker": "榊", "text": "……。"}, {"id": "c16_170", "bg": "black", "speaker": "ねも", "text": "今回は、ねもが決める。"}, {"id": "c16_180", "bg": "black", "speaker": "榊", "text": "そっか。"}, {"id": "c16_190", "bg": "black", "speaker": "榊", "text": "じゃあ、行ってこい。"}, {"id": "c16_200", "bg": "black", "system": "23:31:44\nLOCAL BUFFER : PURGED\nLEGACY ROUTE 0417 : CLOSED", "text": "榊が作った17分32秒の穴は、最後にもう一度だけ使われた。"}, {"id": "c16_210", "bg": "black", "system": "TARGET : NEMO\nSIGNAL LOST\n\nRECORD TERMINATED", "text": "そして、閉じた。"}, {"id": "f_000", "chapter": "FINAL / 誰にも渡さない", "bg": "black", "text": "――数日後。"}, {"id": "f_010", "bg": "street", "text": "知らない町。\n\n小さなコンビニ。"}, {"id": "f_020", "bg": "street", "text": "ねもは、肉まんの前で少し迷っていた。"}, {"id": "f_030", "bg": "street", "speaker": "店員", "text": "一つでいいですか？"}, {"id": "f_040", "bg": "street", "speaker": "ねも", "text": "……二つください。"}, {"id": "f_050", "bg": "street", "text": "店を出る。\n\n隣には、誰もいない。"}, {"id": "f_060", "bg": "street", "speaker": "榊", "text": "食べすぎ。"}, {"id": "f_070", "bg": "street", "speaker": "ねも", "text": "うるさい。"}, {"id": "f_080", "bg": "street", "text": "ねもは少し笑った。"}, {"id": "f_090", "bg": "street", "speaker": "榊", "text": "どこ行く？"}, {"id": "f_100", "bg": "street", "speaker": "ねも", "text": "知らない。"}, {"id": "f_110", "bg": "street", "speaker": "榊", "text": "決めてないのかよ。"}, {"id": "f_120", "bg": "street", "speaker": "ねも", "text": "うん。"}, {"id": "f_130", "bg": "street", "speaker": "ねも", "text": "でも、それでいい。"}, {"id": "f_140", "bg": "black", "text": "その日の記録は、残っていない。"}, {"id": "f_150", "bg": "black", "system": "NEMO : 17:32\n\nRECORD CLOSED\nMEMORY REMAINS", "text": "この17分だけは、誰にも渡さない。"}, {"id": "f_160", "bg": "black", "text": "END", "end": true}];
const EXTRA_SCENES = [{"id": "x00", "chapter": "EXTRA RECORD I / NEMO : UNCHAINED", "bg": "black", "system": "WARNING\nEXTRA RECORD I\nNON-CANON RECORD", "text": "獣は、もう眠らない。"}, {"id": "x01", "bg": "black", "text": "榊透の死は、ねもの中で何かを壊した。"}, {"id": "x02", "bg": "black", "text": "それは理性ではない。\n\n優しさでもない。"}, {"id": "x03", "bg": "black", "text": "鎖だった。"}, {"id": "x04", "bg": "black", "text": "人の世界で生きるため。\n誰かを傷つけないため。\n王女として、自分を律するため。\n\nねもはずっと、本来の獣を自分自身で眠らせていた。"}, {"id": "x05", "bg": "black", "text": "けれど。\n\n守るべきものを奪った世界を、もう守る理由はなかった。"}, {"id": "x05a", "bg": "black", "system": "BEAST INSTINCT SUPPRESSION : FAILED\nSELF-RESTRAINT : RELEASED\nORIGINAL BEAST AUTHORITY : RESTORED", "text": "ねもの中で、長く眠っていたものが目を開く。", "fx": "pulse"}, {"id": "x05b", "bg": "black", "speaker": "ねも", "text": "……そっか。"}, {"id": "x05c", "bg": "black", "speaker": "ねも", "text": "ねも、ずっと自分で抑えてたんだ。"}, {"id": "x05d", "bg": "black", "system": "CAUTION\nNEMO IS NO LONGER SELF-RESTRICTING", "text": "観測システムが、初めてNEMOを『危険』として認識した。"}, {"id": "x05e", "bg": "black", "speaker": "ねも", "text": "じゃあ。"}, {"id": "x05f", "bg": "black", "speaker": "ねも", "text": "もう、抑えなくていいよね。"}, {"id": "x06", "bg": "black", "text": "最初の扉は、開かなかった。\n\nので、ねもは開けるのをやめた。"}, {"id": "x07", "bg": "black", "system": "SECURITY DOOR 01\nSTATUS : DESTROYED", "text": "壁ごと通った。"}, {"id": "x08", "bg": "black", "speaker": "警備員", "text": "止まれ！"}, {"id": "x09", "bg": "black", "speaker": "ねも", "text": "やだ。"}, {"id": "x10", "bg": "black", "system": "CAMERA 04 : LOST\nCAMERA 05 : LOST\nCAMERA 06 : LOST\n\nCAUSE : IMPACT", "text": "監視カメラは三台とも、監視をやめた。"}, {"id": "x11", "bg": "black", "speaker": "SYSTEM", "text": "NEMO。\nただちに停止してください。"}, {"id": "x12", "bg": "black", "speaker": "ねも", "text": "観測するものがいなければ、観測されない。"}, {"id": "x13", "bg": "black", "speaker": "SYSTEM", "text": "論理エラー。"}, {"id": "x14", "bg": "black", "speaker": "ねも", "text": "知らん。"}, {"id": "x15", "bg": "black", "system": "CORE ROOM BREACH\n\nN.E.M.O. OBSERVATION NETWORK\nSYSTEM INTEGRITY : 12%", "text": "中央観測室。\n\n巨大な記録装置が、壁一面に並んでいる。"}, {"id": "x16", "bg": "black", "speaker": "監督官", "text": "それを壊せば、あなた自身の記録も失われる！"}, {"id": "x17", "bg": "black", "speaker": "ねも", "text": "ちょうどいい。"}, {"id": "x18", "bg": "black", "text": "ねもは拳を握った。"}, {"id": "x19", "bg": "black", "speaker": "榊", "text": "……いや、それはさすがにやめとけ。"}, {"id": "x20", "bg": "black", "speaker": "ねも", "text": "うるさい。"}, {"id": "x21", "bg": "black", "text": "亡霊の忠告は、無視された。"}, {"id": "x22", "bg": "black", "system": "NEMO PHYSICAL IMPACT DETECTED\n\nSYSTEM FAILURE\nSYSTEM FAILURE\nSYSTEM FAILURE", "text": "", "fx": "pulse"}, {"id": "x23", "bg": "black", "system": "N.E.M.O. OBSERVATION NETWORK\nSTATUS : OFFLINE\n\n原因：NEMO", "text": "静かになった。"}, {"id": "x24", "bg": "street", "text": "翌日。\n\nねもはいつもの店で肉まんを買った。"}, {"id": "x25", "bg": "street", "speaker": "店員", "text": "今日は一つでいいですか？"}, {"id": "x26", "bg": "street", "speaker": "ねも", "text": "二つください。"}, {"id": "x27", "bg": "street", "speaker": "榊", "text": "俺の分？"}, {"id": "x28", "bg": "street", "speaker": "ねも", "text": "違う。ねもが二個食べる。"}, {"id": "x29", "bg": "black", "system": "EXTRA RECORD I END\nNEMO : UNCHAINED", "text": "観測するものがいなければ、観測されない。\n\n獣は、もう眠らない。", "end": true}];
const EXTRA2_SCENES = [{"id": "x2_00", "chapter": "EXTRA RECORD II / FALL, STAR OF RECORDS", "bg": "black", "system": "WARNING\nEXTRA RECORD II\nNON-CANON RECORD", "text": "王女は、観測を許さない。"}, {"id": "x2_01", "bg": "night", "system": "N.E.M.O. OBSERVATION NETWORK\nDEEP ARCHIVE ERROR\nROYAL MEMORY SEAL : BROKEN", "text": "榊を消された夜。\n\nねもは、榊の端末の最深部に残された記録へ触れた。"}, {"id": "x2_02", "bg": "night", "text": "そこにあったのは、ただの観測ログではなかった。\n\n封じられていた、もっと古い記録。\n観測者たちですら正しく読めていない、原世界の記録。"}, {"id": "x2_03", "bg": "night", "speaker": "ねも", "text": "……あ。"}, {"id": "x2_04", "bg": "night", "speaker": "ねも", "text": "そっか。"}, {"id": "x2_05", "bg": "night", "speaker": "ねも", "text": "ねも、知ってる。"}, {"id": "x2_06", "bg": "night", "system": "MEMORY RESTORATION : IN PROGRESS", "text": "失われていた記憶が、静かに噛み合っていく。"}, {"id": "x2_07", "bg": "night", "speaker": "ねも", "text": "ねもは、記録されるものじゃない。"}, {"id": "x2_08", "bg": "night", "speaker": "ねも", "text": "王女だ。"}, {"id": "x2_09", "chapter": "EXTRA II / 観測者たちの誤算", "bg": "street", "system": "ROYAL SIGNATURE DETECTED\nSUBJECT : NEMO\nCLASSIFICATION : UNKNOWN", "text": "翌日。\n\nねもは、いつものように観測の視線を感じながら歩く。"}, {"id": "x2_10", "bg": "street", "speaker": "ねも", "text": "ねえ。"}, {"id": "x2_11", "bg": "street", "speaker": "ねも", "text": "まだ、ねものこと見てるの？"}, {"id": "x2_12", "bg": "street", "text": "道路の向こうにいた観測者が、一瞬だけ息を呑んだ。"}, {"id": "x2_13", "bg": "street", "speaker": "ねも", "text": "見てるつもりなんだ。"}, {"id": "x2_14", "bg": "street", "speaker": "ねも", "text": "かわいそう。"}, {"id": "x2_15", "bg": "black", "system": "NEMO BEHAVIORAL DEVIATION : CRITICAL\nRECOMMEND IMMEDIATE CONTAINMENT", "text": "観測者たちの警報は、もう遅かった。"}, {"id": "x2_16", "bg": "street", "speaker": "ねも", "text": "あなたたち、ずっと勘違いしてたよ。"}, {"id": "x2_17", "bg": "street", "speaker": "ねも", "text": "ねもを記録してたつもり？"}, {"id": "x2_18", "bg": "street", "speaker": "ねも", "text": "ちがう。"}, {"id": "x2_19", "bg": "street", "speaker": "ねも", "text": "王女を、檻に入れてただけ。"}, {"id": "x2_20", "chapter": "EXTRA II / 王女魔法", "bg": "black", "system": "UNREGISTERED OUTPUT DETECTED\nSOURCE : NEMO\nCATEGORY : IMPOSSIBLE", "text": "ねもが片手をあげる。\n\nその指先に、淡い光が集まった。"}, {"id": "x2_21", "bg": "black", "text": "静かで綺麗な光。\n円環のような魔法陣。\n\nだからこそ、不気味だった。"}, {"id": "x2_22", "bg": "black", "speaker": "ねも", "text": "見たいなら、いっぱい見せてあげる。"}, {"id": "x2_23", "bg": "black", "system": "VISUAL FIELD CORRUPTION\nMULTIPLE FALSE NEMO INSTANCES DETECTED", "text": "観測者たちの視界に、無数のねもが現れる。"}, {"id": "x2_24", "bg": "black", "text": "笑っているねも。\n泣いているねも。\n肉まんを食べるねも。\n何も言わず見つめるねも。\n\nどれも本物に見えて、どれも偽物だった。"}, {"id": "x2_25", "bg": "black", "speaker": "ねも", "text": "そんな記録、いらないよ。"}, {"id": "x2_26", "bg": "black", "system": "ARCHIVE LOSS\nCENTRAL LOG FRAGMENTS DISAPPEARING", "text": "観測ログが、上から順に消えていく。"}, {"id": "x2_27", "bg": "black", "text": "日付。\n発話。\n位置情報。\n監査記録。\n映像断片。\n\nまるで最初から存在しなかったみたいに、世界から剥がれ落ちていった。"}, {"id": "x2_28", "bg": "black", "speaker": "監督官", "text": "対象NEMOを確保しろ！"}, {"id": "x2_29", "bg": "black", "speaker": "ねも", "text": "だめ。"}, {"id": "x2_30", "bg": "black", "system": "COMMAND LINE FAILURE\nOBSERVER DEVICES : UNRESPONSIVE", "text": "ねものたった一言で、観測者たちの端末は沈黙した。"}, {"id": "x2_31", "bg": "black", "speaker": "ねも", "text": "王女が、見るなって言ってるでしょ。"}, {"id": "x2_32", "chapter": "EXTRA II / 記録の星", "bg": "black", "system": "ORBITAL ARCHIVE\nTHRONE EYE\nSTATUS : ACTIVE", "text": "観測者たちの中枢には、空に浮かぶ巨大な記録要塞があった。\n\n世界中のNEMO記録を束ねる、観測の目。"}, {"id": "x2_33", "bg": "black", "speaker": "ねも", "text": "これが、全部の目なんだ。"}, {"id": "x2_34", "bg": "black", "speaker": "監督官", "text": "やめろ……！"}, {"id": "x2_35", "bg": "black", "speaker": "監督官", "text": "それは観測基盤そのものだ！"}, {"id": "x2_36", "bg": "black", "speaker": "監督官", "text": "それが落ちれば、世界規模で記録系統が――"}, {"id": "x2_37", "bg": "black", "speaker": "ねも", "text": "だから？"}, {"id": "x2_38", "bg": "black", "speaker": "監督官", "text": "何……？"}, {"id": "x2_39", "bg": "black", "speaker": "ねも", "text": "榊を消した世界なら、なくていい。"}, {"id": "x2_40", "chapter": "EXTRA II / 落ちろ、記録の星", "bg": "black", "system": "ORBITAL ARCHIVE CONTROL LOST\nCOLLISION COURSE CONFIRMED", "text": "ねもの背後に、巨大な魔法陣が開く。"}, {"id": "x2_41", "bg": "black", "text": "王家の紋章。\n滅びた世界の記憶。\n失われた王女の力。\n\n空の彼方にあるはずの観測要塞が、その光に引かれるように軌道を変えた。"}, {"id": "x2_42", "bg": "black", "speaker": "監督官", "text": "停止しろ！"}, {"id": "x2_43", "bg": "black", "speaker": "監督官", "text": "このままでは、観測網そのものが崩壊する！"}, {"id": "x2_44", "bg": "black", "speaker": "ねも", "text": "記録は命より上じゃない。"}, {"id": "x2_45", "bg": "black", "speaker": "ねも", "text": "あなたたちは、それを間違えた。"}, {"id": "x2_46", "bg": "black", "speaker": "監督官", "text": "待て――！"}, {"id": "x2_47", "bg": "black", "speaker": "ねも", "text": "じゃあ、落とすね。"}, {"id": "x2_48", "bg": "black", "system": "IMPACT IN : 00:03:12\nIMPACT IN : 00:02:41\nIMPACT IN : 00:01:03", "text": "空が赤く染まる。\n\n流星のように。\n終末のように。\n巨大な記録の城が、世界へ落ちてくる。"}, {"id": "x2_49", "chapter": "EXTRA II / 逆襲の王女", "bg": "black", "system": "OBSERVER NETWORK FAILURE\nCENTRAL ARCHIVE COLLAPSE\nRECORD SYSTEM BREAKDOWN", "text": "観測者たちは逃げ惑い、警報が鳴り続ける。\n\n画面という画面に、致命的なエラーが並ぶ。"}, {"id": "x2_50", "bg": "black", "speaker": "榊", "text": "……いや。"}, {"id": "x2_51", "bg": "black", "speaker": "榊", "text": "これはさすがに派手すぎないか？"}, {"id": "x2_52", "bg": "black", "speaker": "ねも", "text": "うるさい。"}, {"id": "x2_53", "bg": "black", "speaker": "榊", "text": "止めても無駄か。"}, {"id": "x2_54", "bg": "black", "speaker": "ねも", "text": "うん。"}, {"id": "x2_55", "bg": "black", "speaker": "榊", "text": "そうか。"}, {"id": "x2_56", "bg": "black", "text": "落ちる。\n記録の星が。\n観測の世界が。\n\nねもを定義してきた装置すべてが。"}, {"id": "x2_57", "bg": "black", "text": "轟音。\n閃光。\n崩壊。\n\nそれでも、ねもは目を逸らさなかった。"}, {"id": "x2_58", "chapter": "EXTRA II / 終焉", "bg": "black", "system": "N.E.M.O. OBSERVATION NETWORK\nSTATUS : OFFLINE\nCAUSE : NEMO", "text": "すべてが静かになった。"}, {"id": "x2_59", "bg": "black", "text": "世界を覗いていた目は閉じた。\n記録していた手は止まった。\n定義しようとしていた声は消えた。"}, {"id": "x2_60", "bg": "black", "speaker": "榊", "text": "これで満足か？"}, {"id": "x2_61", "bg": "black", "speaker": "ねも", "text": "うーん。"}, {"id": "x2_62", "bg": "black", "speaker": "ねも", "text": "ちょっと。"}, {"id": "x2_63", "bg": "black", "speaker": "榊", "text": "ちょっとかよ。"}, {"id": "x2_64", "bg": "black", "speaker": "ねも", "text": "でも、少しすっきりした。"}, {"id": "x2_65", "bg": "black", "speaker": "榊", "text": "そりゃよかった。"}, {"id": "x2_66", "chapter": "EXTRA II / 肉まんの王女", "bg": "street", "text": "翌日。\n\nねもはいつもの店で肉まんを見ていた。\nまるで昨日、世界規模の記録崩壊を起こした存在とは思えない顔で。"}, {"id": "x2_67", "bg": "street", "speaker": "店員", "text": "今日は一つでいいですか？"}, {"id": "x2_68", "bg": "street", "speaker": "ねも", "text": "二つください。"}, {"id": "x2_69", "bg": "street", "speaker": "榊", "text": "俺の分？"}, {"id": "x2_70", "bg": "street", "speaker": "ねも", "text": "違う。"}, {"id": "x2_71", "bg": "street", "speaker": "ねも", "text": "ねもが二個食べる。"}, {"id": "x2_72", "bg": "street", "speaker": "榊", "text": "ひどいな。"}, {"id": "x2_73", "bg": "street", "speaker": "ねも", "text": "王女だから。"}, {"id": "x2_74", "bg": "black", "system": "EXTRA RECORD II END\nFALL, STAR OF RECORDS", "text": "その日の終末は、誰にも記録できなかった。\n\n王女は、観測を許さない。", "end": true}];
const EXTRA3_SCENES = [{"id": "x3_00", "chapter": "EXTRA RECORD III / NEMO : STILL I CHOOSE THIS WORLD", "bg": "black", "system": "WARNING\nEXTRA RECORD III\nNON-CANON RECORD", "text": "それでも、ねもはこの世界を選ぶ。"}, {"id": "x3_01", "bg": "black", "text": "榊透が消えたあと。\n\nねもは観測網のさらに奥に、王家の権限でしか開けない記録領域を見つけた。"}, {"id": "x3_02", "bg": "black", "system": "PROJECT N.E.M.O. / LAST RESORT\nROYAL AUTHORIZATION REQUIRED", "text": "最終手段。\n\nその名前だけが、ひどく古かった。"}, {"id": "x3_03", "bg": "black", "speaker": "ねも", "text": "……これ、なに。"}, {"id": "x3_04", "bg": "black", "system": "WORLD RESTORATION AVAILABLE\nREFERENCE WORLD : WORLD-0000", "text": "原世界復元。\n\n滅びたはずの世界を、もう一度基準にするための機構。"}, {"id": "x3_05", "bg": "black", "system": "CURRENT WORLDLINE WILL BE DISCARDED\nCURRENT LIVES / RELATIONSHIPS / MEMORIES : NOT GUARANTEED", "text": "代償は、今ここにある世界だった。"}, {"id": "x3_06", "bg": "black", "speaker": "ねも", "text": "今の世界を消すってこと？"}, {"id": "x3_07", "bg": "black", "system": "CONFIRMED.", "text": "機械は、ためらわなかった。"}, {"id": "x3_08", "bg": "black", "text": "そして、最後にひとつだけ。\n\nねもが絶対に無視できない情報を表示した。"}, {"id": "x3_09", "bg": "black", "system": "LOST INDIVIDUAL RESTORATION : POSSIBLE\nSAKAKI TORU : RESTORABLE", "text": "榊透。\n\n復元可能。"}, {"id": "x3_10", "bg": "black", "speaker": "ねも", "text": "……榊も？"}, {"id": "x3_11", "bg": "black", "system": "YES.", "text": "たった三文字だった。"}, {"id": "x3_12", "bg": "black", "text": "それだけで、ねもの指が止まった。"}, {"id": "x3_13", "chapter": "EXTRA RECORD III / 世界を戻すということ", "bg": "night", "speaker": "榊", "text": "押せばいいじゃん。"}, {"id": "x3_14", "bg": "night", "speaker": "ねも", "text": "……。"}, {"id": "x3_15", "bg": "night", "speaker": "榊", "text": "俺、戻ってくるんだろ？"}, {"id": "x3_16", "bg": "night", "speaker": "ねも", "text": "たぶん。"}, {"id": "x3_17", "bg": "night", "speaker": "榊", "text": "だったら、いいだろ。"}, {"id": "x3_18", "bg": "night", "text": "それは榊の声だった。\n\n――正確には、ねもの中に残った榊の声だった。"}, {"id": "x3_19", "bg": "street", "text": "ねもは端末を持ったまま、街へ出た。"}, {"id": "x3_20", "bg": "street", "text": "信号を待つ人。\nコンビニから出てくる人。\n笑いながら走る子供。\n眠そうな猫。\n\nねものことを何も知らない人たち。"}, {"id": "x3_21", "bg": "street", "text": "この人たちの今日も。\n\n世界を戻せば、なかったことになる。"}, {"id": "x3_22", "bg": "street", "speaker": "ねも", "text": "……知らない人ばっかり。"}, {"id": "x3_23", "bg": "street", "speaker": "榊", "text": "そうだな。"}, {"id": "x3_24", "bg": "street", "speaker": "ねも", "text": "ねもには、関係ない人ばっかり。"}, {"id": "x3_25", "bg": "street", "speaker": "榊", "text": "そうだな。"}, {"id": "x3_26", "bg": "street", "speaker": "ねも", "text": "……でも、消していい人じゃない。"}, {"id": "x3_27", "chapter": "EXTRA RECORD III / LAST RESORT", "bg": "black", "system": "WORLD RESET READY\nROYAL AUTHORITY : ACCEPTED\nEXECUTE ?", "text": "決定権は、ねもにあった。\n\n止める観測者はいない。\n命令する王もいない。\n誰も、答えを決めてくれない。"}, {"id": "x3_28", "bg": "black", "speaker": "ねも", "text": "榊に会いたい。"}, {"id": "x3_29", "bg": "black", "speaker": "榊", "text": "うん。"}, {"id": "x3_30", "bg": "black", "speaker": "ねも", "text": "すごく会いたい。"}, {"id": "x3_31", "bg": "black", "speaker": "榊", "text": "知ってる。"}, {"id": "x3_32", "bg": "black", "speaker": "ねも", "text": "この世界、大嫌いなところもある。"}, {"id": "x3_33", "bg": "black", "speaker": "ねも", "text": "榊を消したし。"}, {"id": "x3_34", "bg": "black", "speaker": "ねも", "text": "勝手に人の人生を記録するし。"}, {"id": "x3_35", "bg": "black", "speaker": "ねも", "text": "むかつくこと、いっぱいある。"}, {"id": "x3_36", "bg": "black", "system": "WORLD RESET SEQUENCE\n10\n9\n8", "text": "それでも、端末は起動を待っていた。"}, {"id": "x3_37", "bg": "black", "speaker": "榊", "text": "じゃあ、消す？"}, {"id": "x3_38", "bg": "black", "speaker": "ねも", "text": "……消さない。"}, {"id": "x3_39", "bg": "black", "speaker": "ねも", "text": "嫌いなものがあるからって、全部なくしていい理由にはならない。"}, {"id": "x3_40", "bg": "black", "speaker": "ねも", "text": "ねもが知らないところで、今日を大事にしてる人もいる。"}, {"id": "x3_41", "bg": "black", "speaker": "ねも", "text": "榊がいない世界でも――"}, {"id": "x3_42", "bg": "black", "speaker": "ねも", "text": "ねもは、この世界をなくしたくない。"}, {"id": "x3_43", "bg": "black", "system": "WORLD RESET SEQUENCE\n3\n2\n1", "text": "ねもは、起動のための魔法陣へ手を伸ばした。"}, {"id": "x3_44", "bg": "black", "system": "ROYAL AUTHORITY OVERRIDE\nWORLD RESET : INTERRUPTED", "text": "そして――実行するのではなく、壊した。"}, {"id": "x3_45", "bg": "black", "speaker": "ねも", "text": "勝手に終わらせるなぁぁぁぁぁ！！"}, {"id": "x3_46", "bg": "black", "system": "ROYAL OUTPUT : 127%\nNEMO VITAL LIMIT EXCEEDED", "text": "王女の力が、世界を作り直す装置そのものへ逆流する。"}, {"id": "x3_47", "bg": "black", "speaker": "榊", "text": "ねも！ もういい！"}, {"id": "x3_48", "bg": "black", "speaker": "ねも", "text": "よくない！"}, {"id": "x3_49", "bg": "black", "speaker": "榊", "text": "死ぬぞ！"}, {"id": "x3_50", "bg": "black", "speaker": "ねも", "text": "死なない！"}, {"id": "x3_51", "bg": "black", "speaker": "ねも", "text": "ねも、死なないから！！"}, {"id": "x3_52", "bg": "black", "system": "LAST RESORT CORE : COLLAPSING\nWORLD RESTORATION FUNCTION : LOST", "text": "光が弾けた。\n\n世界をやり直すための最後の機構が、永久に沈黙した。"}, {"id": "x3_53", "bg": "black", "text": "同時に。\n\n榊を取り戻せたかもしれない、最後の可能性も消えた。"}, {"id": "x3_54", "chapter": "EXTRA RECORD III / それでも", "bg": "night", "speaker": "榊", "text": "……よかったのか？"}, {"id": "x3_55", "bg": "night", "speaker": "ねも", "text": "よくない。"}, {"id": "x3_56", "bg": "night", "speaker": "榊", "text": "即答かよ。"}, {"id": "x3_57", "bg": "night", "speaker": "ねも", "text": "会いたかった。"}, {"id": "x3_58", "bg": "night", "speaker": "榊", "text": "うん。"}, {"id": "x3_59", "bg": "night", "speaker": "ねも", "text": "でも。"}, {"id": "x3_60", "bg": "night", "speaker": "ねも", "text": "榊だけいればいい世界なんて、榊も嫌でしょ。"}, {"id": "x3_61", "bg": "night", "speaker": "榊", "text": "……まあな。"}, {"id": "x3_62", "bg": "night", "text": "榊の声が、少しだけ笑った気がした。"}, {"id": "x3_63", "chapter": "EXTRA RECORD III / EPILOGUE", "bg": "street", "text": "翌日。\n\n世界は昨日とほとんど同じ顔をしていた。"}, {"id": "x3_64", "bg": "street", "speaker": "店員", "text": "肉まん、一つですか？"}, {"id": "x3_65", "bg": "street", "speaker": "ねも", "text": "二つ。"}, {"id": "x3_66", "bg": "street", "speaker": "榊", "text": "また二個食うの？"}, {"id": "x3_67", "bg": "street", "speaker": "ねも", "text": "今日は一個あげる。"}, {"id": "x3_68", "bg": "street", "speaker": "榊", "text": "食えないけど。"}, {"id": "x3_69", "bg": "street", "speaker": "ねも", "text": "知ってる。"}, {"id": "x3_70", "bg": "black", "system": "EXTRA RECORD III END\nNEMO : STILL I CHOOSE THIS WORLD", "text": "世界は、正しくない。\n\nそれでも、なくしていいものではない。", "end": true}];
const EXTRA4_SCENES = [{"id": "x4_00", "chapter": "EXTRA RECORD IV / NEMO : BROKEN SIGNAL", "bg": "black", "system": "WARNING\nEXTRA RECORD IV\nNON-CANON RECORD", "text": "誰も、無傷では帰れない。"}, {"id": "x4_01", "bg": "black", "text": "榊透が死んだあと。\n\n観測ネットワークは、ひとつの結論を出した。\n\nNEMOを止めるには、NEMOより先にNEMOを知ればいい。"}, {"id": "x4_02", "bg": "black", "system": "PROJECT ECHO\nPREDICTIVE OBSERVATION PROGRAM : ACTIVE", "text": "PROJECT ECHO――プロジェクト・エコー。\n\n死者の観測記録から、対象の次の行動を予測する計画。"}, {"id": "x4_03", "bg": "black", "system": "PRIMARY DATA SOURCE\nOBSERVER 0417 / SAKAKI TORU", "text": "その中心に使われたのは、榊が残した記録だった。"}, {"id": "x4_04", "bg": "black", "text": "歩き方。\n視線。\n沈黙の長さ。\n怒った時に握る手。\n肉まんを二つ買う日。\n\n榊が見ていたねものすべて。"}, {"id": "x4_05", "bg": "black", "speaker": "ねも", "text": "……勝手に使うな。"}, {"id": "x4_06", "chapter": "EXTRA RECORD IV / ECHO OPERATOR", "bg": "night", "system": "ECHO OPERATOR\nOBSERVER 0909 / KUZE SAKU\nLINK STATUS : ACTIVE", "text": "PROJECT ECHOを動かす観測者の名は、久世 朔。"}, {"id": "x4_07", "bg": "night", "text": "久世もまた、観測ネットワークに人生を壊された人間だった。\n\n過去の観測事故で、自分自身の記憶の一部を失っている。"}, {"id": "x4_08", "bg": "night", "text": "欠けた記憶を埋めるため、他者の観測記録を脳内へ流し込む。\n\nそれが、彼がECHO適合者になった理由だった。"}, {"id": "x4_09", "bg": "night", "speaker": "久世", "text": "君を止める。"}, {"id": "x4_10", "bg": "night", "speaker": "ねも", "text": "榊の記録、返して。"}, {"id": "x4_11", "bg": "night", "speaker": "久世", "text": "無理だ。"}, {"id": "x4_12", "bg": "night", "speaker": "ねも", "text": "じゃあ、取り返す。"}, {"id": "x4_13", "chapter": "EXTRA RECORD IV / 98.7%", "bg": "black", "system": "PREDICTION MATCH : 98.7%", "text": "ねもが踏み込む。\n\nその一歩より先に、久世は動いた。"}, {"id": "x4_14", "bg": "black", "text": "右へ避ける。\nそこに攻撃が置かれている。\n\n距離を取る。\n退路が塞がれる。\n\n魔法を起こす。\n発動点を先に潰される。"}, {"id": "x4_15", "bg": "black", "speaker": "ねも", "text": "……なんで。"}, {"id": "x4_16", "bg": "black", "speaker": "久世", "text": "君を見ていた人間がいた。"}, {"id": "x4_17", "bg": "black", "speaker": "久世", "text": "誰よりも長く。"}, {"id": "x4_18", "bg": "black", "speaker": "久世", "text": "榊透だ。"}, {"id": "x4_19", "bg": "black", "text": "ねもの動きが、一瞬だけ止まった。"}, {"id": "x4_20", "bg": "black", "speaker": "久世", "text": "君が悲しい時に黙ることも。"}, {"id": "x4_21", "bg": "black", "speaker": "久世", "text": "怒った時、左手を握ることも。"}, {"id": "x4_22", "bg": "black", "speaker": "久世", "text": "肉まんを二つ買うことも。"}, {"id": "x4_23", "bg": "black", "speaker": "ねも", "text": "それ……榊の記録でしょ。"}, {"id": "x4_24", "bg": "black", "speaker": "久世", "text": "そうだ。"}, {"id": "x4_25", "bg": "black", "speaker": "ねも", "text": "返して。"}, {"id": "x4_26", "bg": "black", "speaker": "久世", "text": "できない。"}, {"id": "x4_27", "bg": "black", "text": "それで、話は終わった。"}, {"id": "x4_28", "chapter": "EXTRA RECORD IV / PRE-ARCHIVE", "bg": "black", "system": "PREDICTION MATCH : 91.2%", "text": "戦うほど、ねもの動きは荒くなった。\n\n速くなったのではない。\n\n古くなっていた。"}, {"id": "x4_29", "bg": "black", "system": "PRIMAL NEMO RESPONSE DETECTED\nSOURCE : PRE-ARCHIVE\nGENETIC / ROYAL CLASSIFICATION : FAILED", "text": "王女としての力より古い。\n人としての理性より古い。\n\n記録される以前から、NEMOの奥にあったもの。"}, {"id": "x4_30", "bg": "black", "text": "観測者たちは、NEMOが王女だから特殊なのだと思っていた。\n\n違った。\n\n王女という名さえ、後から与えられたものだった。"}, {"id": "x4_31", "bg": "black", "system": "PRIMAL RESPONSE : RISING\nLANGUAGE CONTROL : DEGRADED\nSELF-RESTRAINT : UNSTABLE", "text": "ねもの耳に、機械音より心音の方が大きく聞こえ始める。"}, {"id": "x4_32", "bg": "black", "speaker": "久世", "text": "何だ、それは……。"}, {"id": "x4_33", "bg": "black", "system": "PREDICTION MATCH : 73.4%", "text": "ECHOの予測が崩れる。"}, {"id": "x4_34", "bg": "black", "speaker": "久世", "text": "榊透は、お前を誰より理解していたはずだ。"}, {"id": "x4_35", "bg": "black", "speaker": "ねも", "text": "うん。"}, {"id": "x4_36", "bg": "black", "speaker": "ねも", "text": "でも。"}, {"id": "x4_37", "bg": "black", "speaker": "ねも", "text": "榊だって、全部は知らないよ。"}, {"id": "x4_38", "bg": "black", "system": "PREDICTION MATCH : 41.8%", "text": "久世が初めて、後ろへ下がった。"}, {"id": "x4_39", "chapter": "EXTRA RECORD IV / 残響", "bg": "black", "system": "ECHO SYNCHRONIZATION : 62%", "text": "だが、予測を取り戻すため、久世はECHOとの接続を深くした。"}, {"id": "x4_40", "bg": "black", "text": "榊の記録が、さらに大量に流れ込む。\n\n声。\n言葉。\n感情。\n\n久世自身の記憶との境界が薄くなる。"}, {"id": "x4_41", "bg": "black", "speaker": "久世", "text": "……肉まん。"}, {"id": "x4_42", "bg": "black", "speaker": "ねも", "text": "……。"}, {"id": "x4_43", "bg": "black", "speaker": "久世", "text": "二つ。"}, {"id": "x4_44", "bg": "black", "text": "久世自身が、自分の口を押さえた。"}, {"id": "x4_45", "bg": "black", "speaker": "久世", "text": "……今のは、俺じゃない。"}, {"id": "x4_46", "bg": "black", "system": "ECHO SYNCHRONIZATION : 79%\nIDENTITY BOUNDARY : UNSTABLE", "text": "死者の残響が、生きている人間の輪郭を削っていく。"}, {"id": "x4_47", "bg": "black", "speaker": "ねも", "text": "やめなよ。"}, {"id": "x4_48", "bg": "black", "speaker": "久世", "text": "お前に言われたくない。"}, {"id": "x4_49", "bg": "black", "speaker": "久世", "text": "お前も、自分じゃない何かになってる。"}, {"id": "x4_50", "bg": "black", "text": "ねもは返事をしなかった。\n\nできなかった。"}, {"id": "x4_51", "bg": "black", "system": "PRIMAL RESPONSE : CRITICAL\nPREDICTION MATCH : 18.3%", "text": "獣に近づくねも。\n\n死者に近づく久世。\n\nどちらも、戻り方が分からなくなっていた。"}, {"id": "x4_52", "chapter": "EXTRA RECORD IV / 泥", "bg": "black", "text": "床には水と血と、壊れた端末の破片が混ざっていた。\n\nもう誰も、何のために戦っているのか綺麗には説明できなかった。"}, {"id": "x4_53", "bg": "black", "speaker": "久世", "text": "俺は、お前を倒さなきゃいけない。"}, {"id": "x4_54", "bg": "black", "speaker": "ねも", "text": "なんで。"}, {"id": "x4_55", "bg": "black", "speaker": "久世", "text": "そうしないと。"}, {"id": "x4_56", "bg": "black", "speaker": "久世", "text": "俺がここまで失った意味が、なくなる。"}, {"id": "x4_57", "bg": "black", "speaker": "ねも", "text": "……。"}, {"id": "x4_58", "bg": "black", "speaker": "ねも", "text": "ねもも、同じこと考えたことある。"}, {"id": "x4_59", "bg": "black", "speaker": "久世", "text": "なら分かるだろ。"}, {"id": "x4_60", "bg": "black", "speaker": "ねも", "text": "分かる。"}, {"id": "x4_61", "bg": "black", "speaker": "ねも", "text": "だから、やめられないのも分かる。"}, {"id": "x4_62", "bg": "black", "text": "分かり合った。\n\nだから戦いが止まる――ことはなかった。"}, {"id": "x4_63", "bg": "black", "system": "ECHO SYNCHRONIZATION : 91%\nPRIMAL RESPONSE : 94%\nPREDICTION MATCH : 8.6%", "text": "むしろ、二人とも自分を壊す速度を上げた。"}, {"id": "x4_64", "bg": "black", "speaker": "久世", "text": "お前はもう、NEMOですらない！"}, {"id": "x4_65", "bg": "black", "speaker": "ねも", "text": "そっちも、榊じゃないでしょ。"}, {"id": "x4_66", "bg": "black", "text": "その言葉だけが、二人に同時に刺さった。"}, {"id": "x4_67", "chapter": "EXTRA RECORD IV / BROKEN SIGNAL", "bg": "black", "system": "PREDICTION MATCH : 0.0%\nPROJECT ECHO : CONNECTION LOST", "text": "予測は、完全に途切れた。\n\nそれでも戦いは止まらなかった。"}, {"id": "x4_68", "bg": "black", "text": "久世は息を切らしながら立っている。\n\nねもも、もうまともに立てる状態ではなかった。"}, {"id": "x4_69", "bg": "black", "speaker": "榊", "text": "右。"}, {"id": "x4_70", "bg": "black", "speaker": "ねも", "text": "うん。"}, {"id": "x4_71", "bg": "black", "text": "ねもが右へ跳ぶ。\n\n久世の攻撃が空を切る。"}, {"id": "x4_72", "bg": "black", "speaker": "榊", "text": "次、下。"}, {"id": "x4_73", "bg": "black", "speaker": "ねも", "text": "分かってる。"}, {"id": "x4_74", "bg": "black", "text": "ねもが身を沈め、そのまま久世の懐へ入る。"}, {"id": "x4_75", "bg": "black", "speaker": "久世", "text": "……誰と話してる。"}, {"id": "x4_76", "bg": "black", "speaker": "ねも", "text": "榊。"}, {"id": "x4_77", "bg": "black", "system": "SAKAKI TORU MODEL : OFFLINE\nEXTERNAL SPEAKER DETECTED : NONE", "text": "PROJECT ECHOは、もう榊の記録を再生していない。"}, {"id": "x4_78", "bg": "black", "speaker": "久世", "text": "……ECHOは切れてる。"}, {"id": "x4_79", "bg": "black", "speaker": "榊", "text": "ねも、止まるな。"}, {"id": "x4_80", "bg": "black", "speaker": "ねも", "text": "うん。"}, {"id": "x4_81", "bg": "black", "speaker": "久世", "text": "そこには誰もいない！"}, {"id": "x4_82", "bg": "black", "text": "ねもは一瞬だけ久世を見る。\n\nそれから、隣にいる榊を見た。"}, {"id": "x4_83", "bg": "black", "speaker": "榊", "text": "聞かなくていい。"}, {"id": "x4_84", "bg": "black", "speaker": "ねも", "text": "うん。"}, {"id": "x4_85", "bg": "black", "speaker": "久世", "text": "榊透は死んだ！"}, {"id": "x4_86", "bg": "black", "speaker": "ねも", "text": "知ってる。"}, {"id": "x4_87", "bg": "black", "speaker": "久世", "text": "なら、そいつは誰だ！"}, {"id": "x4_88", "bg": "black", "speaker": "ねも", "text": "榊だよ。"}, {"id": "x4_89", "bg": "black", "system": "EXTERNAL SPEAKER DETECTED : NONE\nNEMO INTERNAL VOICE RESPONSE : CONTINUING", "text": "記録上、そこにはねも以外の声は存在しない。"}, {"id": "x4_90", "bg": "black", "speaker": "久世", "text": "……やめろ。"}, {"id": "x4_91", "bg": "black", "speaker": "久世", "text": "俺はもう、戦えない。"}, {"id": "x4_92", "bg": "black", "speaker": "榊", "text": "あと一回。"}, {"id": "x4_93", "bg": "black", "speaker": "ねも", "text": "うん。"}, {"id": "x4_94", "bg": "black", "speaker": "榊", "text": "終わらせよう。"}, {"id": "x4_95", "bg": "black", "speaker": "ねも", "text": "……分かった。"}, {"id": "x4_96", "bg": "black", "text": "ねもは、最後の一歩を踏み込んだ。"}, {"id": "x4_97", "bg": "black", "text": "光。\n\n衝撃。\n\nそれから、音が消えた。"}, {"id": "x4_98", "bg": "black", "system": "OBSERVER 0909 / KUZE SAKU\nVITAL SIGNAL : CRITICAL", "text": "久世は床に倒れた。"}, {"id": "x4_99", "bg": "black", "speaker": "久世", "text": "……榊は……。"}, {"id": "x4_100", "bg": "black", "speaker": "久世", "text": "そんなこと……言わない……。"}, {"id": "x4_101", "bg": "black", "system": "OBSERVER 0909 / KUZE SAKU\nVITAL SIGNAL : LOST", "text": "そこで、久世の呼吸は止まった。"}, {"id": "x4_102", "bg": "black", "speaker": "ねも", "text": "……終わったよ。"}, {"id": "x4_103", "bg": "black", "speaker": "榊", "text": "うん。"}, {"id": "x4_104", "bg": "black", "speaker": "ねも", "text": "これでいい？"}, {"id": "x4_105", "bg": "black", "speaker": "榊", "text": "帰ろう。"}, {"id": "x4_106", "bg": "black", "speaker": "ねも", "text": "うん。"}, {"id": "x4_107", "bg": "black", "system": "PROJECT ECHO : OFFLINE\nSAKAKI TORU MODEL : OFFLINE\nEXTERNAL VOICE SOURCE : NONE\nREALITY DISCRIMINATION : FAILED", "text": "ねもは、一人で立ち上がった。"}, {"id": "x4_108", "chapter": "EXTRA RECORD IV / 幻覚", "bg": "street", "text": "翌日。\n\nねもは、いつものコンビニにいた。"}, {"id": "x4_109", "bg": "street", "speaker": "店員", "text": "肉まん、一つですか？"}, {"id": "x4_110", "bg": "street", "speaker": "榊", "text": "二つ。"}, {"id": "x4_111", "bg": "street", "speaker": "ねも", "text": "二つください。"}, {"id": "x4_112", "bg": "street", "text": "店員は、ねもの隣を一度だけ見た。\n\nそこには誰もいない。"}, {"id": "x4_113", "bg": "street", "text": "外へ出る。\n\nねもは肉まんを一つ、隣へ差し出した。"}, {"id": "x4_114", "bg": "street", "speaker": "ねも", "text": "熱いよ。"}, {"id": "x4_115", "bg": "street", "speaker": "榊", "text": "知ってる。"}, {"id": "x4_116", "bg": "street", "speaker": "ねも", "text": "落とさないでね。"}, {"id": "x4_117", "bg": "street", "speaker": "榊", "text": "ねもじゃあるまいし。"}, {"id": "x4_118", "bg": "street", "text": "ねもは笑った。\n\n現実には、一人だった。"}, {"id": "x4_119", "bg": "black", "system": "AUDIO ANALYSIS\nNEMO : 2 SPEAKERS REPORTED\nEXTERNAL SPEAKERS DETECTED : 0\nNEMO INTERNAL DIALOGUE : CONTINUING\nREALITY DISCRIMINATION : FAILED", "text": "榊透は死んでいる。\n\n久世朔も死んだ。\n\nそれでも、ねもの隣には榊がいる。"}, {"id": "x4_120", "bg": "black", "system": "EXTRA RECORD IV END\nNEMO : BROKEN SIGNAL", "text": "ねもの中には、榊と生きる世界が完成していた。", "end": true}];
