function clearEndAutoReturn(){
  if(endAutoReturnTimer){
    clearTimeout(endAutoReturnTimer);
    endAutoReturnTimer = null;
  }
  if(endAutoReturnToastTimer){
    clearTimeout(endAutoReturnToastTimer);
    endAutoReturnToastTimer = null;
  }
}

function scheduleEndAutoReturn(){
  clearEndAutoReturn();
  showToast("5秒後にタイトルへ戻ります");
  endAutoReturnToastTimer = setTimeout(()=>{
    if(index === currentScenes().length - 1 && currentScenes()[index]?.end){
      showToast("タイトルへ戻ります");
    }
  }, 2400);
  endAutoReturnTimer = setTimeout(()=>{
    if(index === currentScenes().length - 1 && currentScenes()[index]?.end){
      goTitle();
    }
  }, END_AUTO_RETURN_MS);
}


function isMainCleared(){
  if(localStorage.getItem(MAIN_CLEAR_KEY) === "1") return true;

  // Migration aid: if an older manual save is already at FINAL/END, count it as cleared.
  const keys = [SAVE_KEY, ...LEGACY_SAVE_KEYS];
  for(const key of keys){
    const raw = localStorage.getItem(key);
    if(!raw) continue;
    try{
      const data = JSON.parse(raw);
      if(data.sceneId === "f_160" || (data.chapter || "").startsWith("FINAL")){
        localStorage.setItem(MAIN_CLEAR_KEY, "1");
        return true;
      }
    }catch(e){}
  }
  return false;
}

function updateExtraUnlock(){
  const unlocked = isMainCleared();

  extraBtn.disabled = !unlocked;
  extra2Btn.disabled = !unlocked;
  extra3Btn.disabled = !unlocked;
  extra4Btn.disabled = !unlocked;
  extra5Btn.disabled = !unlocked;

  extraBtn.textContent = unlocked ? "EXTRA RECORD I" : "EXTRA RECORD I / LOCKED";
  extra2Btn.textContent = unlocked ? "EXTRA RECORD II" : "EXTRA RECORD II / LOCKED";
  extra3Btn.textContent = unlocked ? "EXTRA RECORD III" : "EXTRA RECORD III / LOCKED";
  extra4Btn.textContent = unlocked ? "EXTRA RECORD IV" : "EXTRA RECORD IV / LOCKED";
  extra5Btn.textContent = unlocked ? "EXTRA RECORD V" : "EXTRA RECORD V / LOCKED";

  extraBtn.title = unlocked ? "NEMO : UNCHAINED" : "本編クリア後に解禁";
  extra2Btn.title = unlocked ? "FALL, STAR OF RECORDS" : "本編クリア後に解禁";
  extra3Btn.title = unlocked ? "NEMO : STILL I CHOOSE THIS WORLD" : "本編クリア後に解禁";
  extra4Btn.title = unlocked ? "NEMO : BROKEN SIGNAL" : "本編クリア後に解禁";
  extra5Btn.title = unlocked ? "NEMO : GIVE HIM BACK" : "本編クリア後に解禁";
}

function markMainCleared(){
  if(localStorage.getItem(MAIN_CLEAR_KEY) === "1") return;
  localStorage.setItem(MAIN_CLEAR_KEY, "1");
  unlockAllMainArchive(true);
  updateExtraUnlock();
  showToast("MAIN RECORD COMPLETE / EXTRA RECORDS UNLOCKED");
}


function currentScenes(){
  if(mode === "extra") return EXTRA_SCENES;
  if(mode === "extra2") return EXTRA2_SCENES;
  if(mode === "extra3") return EXTRA3_SCENES;
  if(mode === "extra4") return EXTRA4_SCENES;
  if(mode === "extra5") return EXTRA5_SCENES;
  return SCENES;
}



function getArchiveUnlocks(){
  try{
    const raw = localStorage.getItem(ARCHIVE_KEY);
    const ids = raw ? JSON.parse(raw) : [];
    const allowed = new Set(ARCHIVE_ITEMS.map(item=>item.id));
    const current = new Set((Array.isArray(ids) ? ids : []).filter(id=>allowed.has(id)));

    if(current.size === 0){
      for(const key of LEGACY_ARCHIVE_KEYS){
        const legacyRaw = localStorage.getItem(key);
        if(!legacyRaw) continue;
        const legacyIds = JSON.parse(legacyRaw);
        if(!Array.isArray(legacyIds)) continue;
        ARCHIVE_ITEMS.forEach(item=>{
          if(item.legacyId && legacyIds.includes(item.legacyId)) current.add(item.id);
        });
      }
      if(current.size) localStorage.setItem(ARCHIVE_KEY, JSON.stringify([...current]));
    }
    return current;
  }catch(e){
    return new Set();
  }
}

function saveArchiveUnlocks(set){
  localStorage.setItem(ARCHIVE_KEY, JSON.stringify([...set]));
}

function unlockArchiveItem(id, silent=false){
  const unlocked = getArchiveUnlocks();
  if(unlocked.has(id)) return false;
  unlocked.add(id);
  saveArchiveUnlocks(unlocked);
  if(!silent){
    showToast(`ARCHIVE RECORD ${id} / RECOVERED`);
    beep(820,.06,.018);
  }
  return true;
}

function unlockAllMainArchive(silent=true){
  const unlocked = getArchiveUnlocks();
  let changed = false;
  ARCHIVE_ITEMS.filter(item=>item.mode === "main").forEach(item=>{
    if(!unlocked.has(item.id)){
      unlocked.add(item.id);
      changed = true;
    }
  });
  if(changed) saveArchiveUnlocks(unlocked);
  if(changed && !silent) showToast("MAIN ARCHIVE RECOVERED");
}

function unlockArchiveForScene(sceneId, sceneMode=mode, silent=false){
  const item = ARCHIVE_ITEMS.find(a=>a.mode === sceneMode && a.trigger === sceneId);
  if(item) unlockArchiveItem(item.id, silent);
}

function migrateArchiveProgress(){
  if(isMainCleared()){
    unlockAllMainArchive(true);
    return;
  }

  const raw = getAvailableSave();
  if(!raw) return;
  try{
    const data = JSON.parse(raw);
    const saveIndex = SCENES.findIndex(s=>s.id === data.sceneId);
    if(saveIndex < 0) return;

    const sceneIndex = new Map(SCENES.map((s,i)=>[s.id,i]));
    const unlocked = getArchiveUnlocks();
    let changed = false;
    ARCHIVE_ITEMS.filter(item=>item.mode === "main").forEach(item=>{
      const triggerIndex = sceneIndex.get(item.trigger);
      if(Number.isInteger(triggerIndex) && triggerIndex <= saveIndex && !unlocked.has(item.id)){
        unlocked.add(item.id);
        changed = true;
      }
    });
    if(changed) saveArchiveUnlocks(unlocked);
  }catch(e){}
}

function renderArchive(){
  const unlocked = getArchiveUnlocks();
  archiveCount.textContent = `${String(unlocked.size).padStart(2,"0")} / ${ARCHIVE_ITEMS.length}`;
  archiveGrid.innerHTML = "";

  ARCHIVE_ITEMS.forEach(item=>{
    const isUnlocked = unlocked.has(item.id);
    const card = document.createElement("button");
    card.type = "button";
    card.className = `archive-card ${isUnlocked ? "unlocked" : "locked"}`;
    card.setAttribute("aria-disabled", isUnlocked ? "false" : "true");

    if(isUnlocked){
      card.innerHTML = `
        <span class="archive-thumb"><img src="${item.image}" alt="" loading="lazy"></span>
        <span class="archive-card-copy">
          <span class="archive-card-no">RECORD ${item.id}</span>
          <strong>${escapeHtml(item.title)}</strong>
          <span>${escapeHtml(item.jp)}</span>
        </span>`;
      card.onclick = ()=>openStill(item.id);
    }else{
      card.innerHTML = `
        <span class="archive-thumb archive-thumb-locked">
          <span class="archive-lock-mark">LOCKED</span>
          <span class="archive-lock-no">${item.id}</span>
        </span>
        <span class="archive-card-copy">
          <span class="archive-card-no">RECORD ${item.id}</span>
          <strong>UNRECOVERED</strong>
          <span>この記録はまだ回収されていません。</span>
        </span>`;
      card.onclick = ()=>showToast(`RECORD ${item.id} / LOCKED`);
    }
    archiveGrid.appendChild(card);
  });
}

