function goTitle(){
  clearEndAutoReturn();
  closeStillViewer();
  archiveScreen.classList.remove("active");
  gameScreen.classList.remove("active");
  titleScreen.classList.add("active");
  updateContinue();
  updateExtraUnlock();
}

function saveGame(){
  if(mode !== "main"){ showToast("EXTRAではSAVEできません"); return; }
  const sceneList = currentScenes();
  const s = sceneList[index];
  const data = {
    sceneId:s.id,
    index,
    chapter:chapterLabel.textContent,
    log
  };
  localStorage.setItem(SAVE_KEY, JSON.stringify(data));
  showToast("SAVE COMPLETE");
  updateContinue();
}

function getAvailableSave(){
  const current = localStorage.getItem(SAVE_KEY);
  if(current) return current;
  for(const k of LEGACY_SAVE_KEYS){
    const legacy = localStorage.getItem(k);
    if(legacy) return legacy;
  }
  return null;
}

function loadGame(){
  clearEndAutoReturn();
  mode = "main";
  const raw = getAvailableSave();
  if(!raw){ showToast("NO SAVE DATA"); return; }
  const data = JSON.parse(raw);
  let loadIndex = SCENES.findIndex(s=>s.id === data.sceneId);
  if(loadIndex < 0) loadIndex = Math.min(data.index || 0, SCENES.length-1);
  titleScreen.classList.remove("active");
  gameScreen.classList.add("active");
  log = data.log || [];
  chapterLabel.textContent = data.chapter || "PROLOGUE / 観測者";
  SCENES.forEach(s=>delete s._choiceResolved);
  showScene(loadIndex, true);
  showToast("LOAD COMPLETE");
}

function updateContinue(){
  document.getElementById("continueBtn").disabled = !getAvailableSave();
}

function openLog(){
  logContent.innerHTML = "";
  log.forEach(e=>{
    const d = document.createElement("div");
    d.className = "log-entry";
    d.innerHTML = (e.speaker ? `<strong>${escapeHtml(e.speaker)}</strong>` : "") + escapeHtml(e.text).replace(/\n/g,"<br>");
    logContent.appendChild(d);
  });
  logPanel.classList.remove("hidden");
  logContent.scrollTop = logContent.scrollHeight;
}

function escapeHtml(str){
  return (str || "").replace(/[&<>"']/g, c=>({"&":"&amp;","<":"&lt;",">":"&gt;","\"":"&quot;","'":"&#039;"}[c]));
}

function showToast(msg){
  toast.textContent = msg;
  toast.classList.remove("hidden");
  setTimeout(()=>toast.classList.add("hidden"),1300);
}

document.getElementById("startBtn").onclick = startGame;
document.getElementById("continueBtn").onclick = loadGame;
document.getElementById("extraBtn").onclick = startExtra;
document.getElementById("extra2Btn").onclick = startExtra2;
document.getElementById("extra3Btn").onclick = startExtra3;
document.getElementById("extra4Btn").onclick = startExtra4;
document.getElementById("extra5Btn").onclick = startExtra5;
archiveBtn.onclick = openArchive;
archiveBackBtn.onclick = closeArchive;
stillViewerClose.onclick = closeStillViewer;
stillPrevBtn.onclick = ()=>navigateStill(-1);
stillNextBtn.onclick = ()=>navigateStill(1);
stillViewer.onclick = (e)=>{
  if(e.target === stillViewer) closeStillViewer();
};
document.getElementById("saveBtn").onclick = saveGame;
document.getElementById("loadBtn").onclick = loadGame;
document.getElementById("logBtn").onclick = openLog;
document.getElementById("closeLogBtn").onclick = ()=>logPanel.classList.add("hidden");
document.getElementById("titleBtn").onclick = goTitle;
soundBtn.onclick = ()=>{
  soundOn = !soundOn;
  soundBtn.textContent = soundOn ? "SOUND ON" : "SOUND OFF";
  if(soundOn) beep();
};

document.getElementById("stage").addEventListener("click", (e)=>{
  if(e.target.tagName === "BUTTON") return;
  advance();
});

window.addEventListener("keydown",(e)=>{
  if(!stillViewer.classList.contains("hidden")){
    if(e.key === "Escape") closeStillViewer();
    if(e.key === "ArrowLeft") navigateStill(-1);
    if(e.key === "ArrowRight") navigateStill(1);
    return;
  }

  if(archiveScreen.classList.contains("active")){
    if(e.key === "Escape") closeArchive();
    return;
  }

  if(e.key === "Escape" && !logPanel.classList.contains("hidden")){
    logPanel.classList.add("hidden");
    return;
  }

  if(gameScreen.classList.contains("active") && ["Enter"," ","ArrowRight"].includes(e.key)){
    e.preventDefault();
    advance();
  }
});

migrateArchiveProgress();
updateContinue();
updateExtraUnlock();
